{"command":"python3 - << 'PY'
import pty, os, sys, time, select
def interact(args, inputs, wait=0.5):
    # use pty
    pid, fd = pty.fork()
    if pid == 0:
        os.execv("/workspace/executable", ["/workspace/executable"]+args)
    else:
        out=b""
        def read_all(timeout=0.8):
            nonlocal out
            data=b""
            end=time.time()+timeout
            while time.time()<end:
                r,_,_=select.select([fd],[],[],0.1)
                if r:
                    try:
                        chunk=os.read(fd, 4096)
                    except OSError:
                        break
                    if not chunk:
                        break
                    data+=chunk
                    end=time.time()+0.4
            return data
        initial=read_all(1.0)
        print("ARGS",args)
        print("INITIAL",initial)
        for inp in inputs:
            print(f">>> SEND {inp!r}")
            os.write(fd, inp.encode())
            d=read_all(1.0)
            print("RESP",d)
        # try ctrl-d
        try:
            os.write(fd, b"\x04")
            print("after EOF", read_all(1.0))
        except OSError as e:
            print(e)
        try:
            _, status=os.waitpid(pid, os.WNOHANG)
            print("status wn", status)
            if status==0:
                # still? kill
                import signal
                os.kill(pid, signal.SIGKILL)
                print(os.waitpid(pid,0))
            else:
                print("exit code", os.waitstatus_to_exitcode(status))
        except Exception as e:
            print("wait err",e)

interact([], ["print(123)\n", "1+1\n"])
print("\n==== python repl ====")
interact(["python"], ["print(456)\n","x=5\n","print(x)\n"])
PY"}

