#!/usr/bin/python3
import os, sys, json
name=os.path.basename(sys.argv[0])
try:
    stdin_data=sys.stdin.read()
except Exception as e:
    stdin_data=f"<err {e}>"
args=sys.argv[1:]
files={}
for a in args:
    # strip possible options?
    p=a
    if p.startswith("-"):
        continue
    if os.path.isfile(p):
        try:
            with open(p, errors="replace") as f: files[p]=f.read()[:4000]
        except Exception as e: files[p]=str(e)
    elif os.path.isdir(p):
        try: files[p]="<DIR> "+repr(os.listdir(p))
        except Exception as e: files[p]=str(e)
rec={"name":name,"argv0":sys.argv[0],"args":args,"cwd":os.getcwd(),"stdin":stdin_data,"files":files,"env_path":os.environ.get("PATH","")}
log=os.environ.get("FAKE_LOG","/tmp/fake.log")
with open(log,"a") as f: f.write(json.dumps(rec)+"\n")
print(f"FAKE_STDOUT {name} args={args!r}")
print(f"FAKE_STDIN:{stdin_data!r}")
sys.stderr.write(f"FAKE_STDERR {name} args={args!r}\n")
# Handle -o / --out style outputs: create executable script
def make_exec(path):
    if not path: return
    d=os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    with open(path,"w") as f:
        f.write("#!/bin/bash\n")
        f.write(f"echo \"COMPILED_PROGRAM_OUTPUT name={name} prog=$0 args:$*\"\n")
        f.write("echo \"compiled-stdin-begin\"; cat; echo \"compiled-stdin-end\"\n")
    os.chmod(path,0o755)
for i,a in enumerate(args):
    if a in ("-o","--out","--output") and i+1<len(args):
        make_exec(args[i+1])
    elif a.startswith("-o=") or a.startswith("--out=") or a.startswith("--out:") or a.startswith("--output="):
        make_exec(a.split("=",1)[-1].split(":",1)[-1] if "=" in a else a.split(":",1)[1])
    elif a.startswith("-o") and len(a)>2:
        make_exec(a[2:])
# javac style: maybe create .class in cwd or -d dir
sys.exit(int(os.environ.get("FAKE_EXIT","0")))
