#!/usr/bin/python3
import os,sys,json
name=os.path.basename(sys.argv[0]); args=sys.argv[1:]
files={}
for a in args:
    if a.startswith("-"): continue
    if os.path.isfile(a):
        try: files[a]=open(a,errors="replace").read()[:5000]
        except Exception as e: files[a]=str(e)
    elif os.path.isdir(a):
        files[a]="<DIR> "+repr(os.listdir(a))
def logrec(stdin_data, extra=None):
    rec={"name":name,"argv0":sys.argv[0],"args":args,"cwd":os.getcwd(),"stdin":stdin_data,"files":files}
    if extra: rec.update(extra)
    with open(os.environ.get("FAKE_LOG","/tmp/fake.log"),"a") as f: f.write(json.dumps(rec)+"\n")
logrec("__START__")
print(f"FAKE_START {name} args={args!r}", flush=True)
sys.stderr.write(f"FAKE_START_ERR {name} args={args!r}\n"); sys.stderr.flush()
def make_exec(path):
    if not path: return
    d=os.path.dirname(path)
    if d: os.makedirs(d,exist_ok=True)
    with open(path,"w") as f:
        f.write("#!/bin/bash\n")
        f.write(f"echo \"COMPILED_PROGRAM_OUTPUT prog=$0 args:$*\"\n")
        f.write("cat\n")
    os.chmod(path,0o755)
for i,a in enumerate(args):
    if a in ("-o","--out","--output") and i+1<len(args): make_exec(args[i+1])
    elif a.startswith("-o="): make_exec(a[3:])
    elif a.startswith("--out:"): make_exec(a.split(":",1)[1])
    elif a.startswith("-o") and len(a) > 2: make_exec(a[2:])
if os.isatty(0):
    logrec("<tty>")
else:
    # line buffered read
    try:
        for line in sys.stdin:
            logrec(line, {"line":True})
            print(f"FAKE_ECHO_STDOUT {line.rstrip()}", flush=True)
            sys.stderr.write(f"FAKE_ECHO_STDERR {line.rstrip()}\n"); sys.stderr.flush()
    except Exception as e:
        logrec(f"<read err {e}>")
sys.exit(int(os.environ.get("FAKE_EXIT","0")))
