import pty,os,time,select,sys,re

def is_incomplete(lang,line):
    env=dict(os.environ); env["HOME"]="/tmp/hinc"
    pid,fd=pty.fork()
    if pid==0: os.execve("/workspace/executable",["/workspace/executable",lang],env)
