use anyhow::{anyhow, Result};
use std::ffi::OsStr;
use std::path::{Path, PathBuf};

pub const AVAILABLE: &str = "bash, c, cpp, crystal, csharp, dart, elixir, go, groovy, haskell, java, javascript, julia, kotlin, lua, nim, perl, php, python, r, ruby, rust, swift, typescript, zig";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Language {
    Bash,
    C,
    Cpp,
    Crystal,
    CSharp,
    Dart,
    Elixir,
    Go,
    Groovy,
    Haskell,
    Java,
    JavaScript,
    Julia,
    Kotlin,
    Lua,
    Nim,
    Perl,
    Php,
    Python,
    R,
    Ruby,
    Rust,
    Swift,
    TypeScript,
    Zig,
}

impl Language {
    pub fn id(self) -> &'static str {
        match self {
            Language::Bash => "bash",
            Language::C => "c",
            Language::Cpp => "cpp",
            Language::Crystal => "crystal",
            Language::CSharp => "csharp",
            Language::Dart => "dart",
            Language::Elixir => "elixir",
            Language::Go => "go",
            Language::Groovy => "groovy",
            Language::Haskell => "haskell",
            Language::Java => "java",
            Language::JavaScript => "javascript",
            Language::Julia => "julia",
            Language::Kotlin => "kotlin",
            Language::Lua => "lua",
            Language::Nim => "nim",
            Language::Perl => "perl",
            Language::Php => "php",
            Language::Python => "python",
            Language::R => "r",
            Language::Ruby => "ruby",
            Language::Rust => "rust",
            Language::Swift => "swift",
            Language::TypeScript => "typescript",
            Language::Zig => "zig",
        }
    }

    pub fn all() -> [Language; 25] {
        [
            Language::Bash, Language::C, Language::Cpp, Language::Crystal, Language::CSharp,
            Language::Dart, Language::Elixir, Language::Go, Language::Groovy, Language::Haskell,
            Language::Java, Language::JavaScript, Language::Julia, Language::Kotlin, Language::Lua,
            Language::Nim, Language::Perl, Language::Php, Language::Python, Language::R,
            Language::Ruby, Language::Rust, Language::Swift, Language::TypeScript, Language::Zig,
        ]
    }

    pub fn parse(raw: &str) -> Option<Language> {
        let s = raw.trim().to_ascii_lowercase();
        let lang = match s.as_str() {
            "bash" | "sh" | "shell" | "zsh" => Language::Bash,
            "c" => Language::C,
            "cpp" | "c++" => Language::Cpp,
            "crystal" | "cr" | "crystal-lang" => Language::Crystal,
            "csharp" | "cs" | "c#" | "dotnet" => Language::CSharp,
            "dart" | "flutter" | "dartlang" => Language::Dart,
            "elixir" | "ex" | "exs" => Language::Elixir,
            "go" | "golang" => Language::Go,
            "groovy" | "groovysh" => Language::Groovy,
            "haskell" | "hs" | "ghci" => Language::Haskell,
            "java" => Language::Java,
            "javascript" | "js" | "node" | "nodejs" | "ecmascript" => Language::JavaScript,
            "julia" | "jl" => Language::Julia,
            "kotlin" | "kt" | "kts" => Language::Kotlin,
            "lua" | "luajit" => Language::Lua,
            "nim" | "nimlang" => Language::Nim,
            "perl" | "pl" => Language::Perl,
            "php" | "php-cli" => Language::Php,
            "python" | "python3" | "py" | "py3" => Language::Python,
            "r" | "rscript" => Language::R,
            "ruby" | "rb" => Language::Ruby,
            "rust" | "rs" => Language::Rust,
            "swift" | "swiftlang" => Language::Swift,
            "typescript" | "ts" | "deno" | "ts-node" => Language::TypeScript,
            "zig" | "ziglang" => Language::Zig,
            _ => return None,
        };
        Some(lang)
    }

    pub fn parse_cli(raw: &str) -> Result<Language> {
        Language::parse(raw).ok_or_else(|| {
            anyhow!(
                "Unknown language '{}'. Available languages: {}",
                raw.trim().to_ascii_lowercase(),
                AVAILABLE
            )
        })
    }

    pub fn parse_repl(raw: &str) -> Result<Language> {
        Language::parse(raw).ok_or_else(|| {
            anyhow!(
                "language '{}' not supported. Available: {}",
                raw.trim().to_ascii_lowercase(),
                AVAILABLE
            )
        })
    }

    pub fn from_extension(ext: &str) -> Option<Language> {
        let e = ext.to_ascii_lowercase();
        let lang = match e.as_str() {
            "sh" | "bash" | "zsh" => Language::Bash,
            "c" => Language::C,
            "cpp" | "cxx" | "cc" | "hpp" | "hxx" => Language::Cpp,
            "cr" => Language::Crystal,
            "cs" => Language::CSharp,
            "dart" => Language::Dart,
            "ex" | "exs" => Language::Elixir,
            "go" => Language::Go,
            "groovy" => Language::Groovy,
            "hs" => Language::Haskell,
            "java" => Language::Java,
            "js" | "mjs" | "cjs" | "jsx" => Language::JavaScript,
            "jl" | "julia" => Language::Julia,
            "kt" | "kts" => Language::Kotlin,
            "lua" => Language::Lua,
            "nim" => Language::Nim,
            "pl" | "pm" | "perl" => Language::Perl,
            "php" => Language::Php,
            "py" | "pyw" => Language::Python,
            "r" => Language::R,
            "rb" => Language::Ruby,
            "rs" => Language::Rust,
            "swift" => Language::Swift,
            "ts" | "tsx" => Language::TypeScript,
            "zig" => Language::Zig,
            _ => return None,
        };
        Some(lang)
    }

    pub fn from_path(path: &Path) -> Language {
        path.extension()
            .and_then(OsStr::to_str)
            .and_then(Language::from_extension)
            .unwrap_or(Language::Python)
    }
}

pub fn looks_like_file(raw: &str) -> bool {
    let path = Path::new(raw);
    if path.exists() {
        return true;
    }
    if raw.contains('/') || raw.contains('\\') {
        return true;
    }
    if let Some(ext) = path.extension().and_then(OsStr::to_str) {
        let e = ext.to_ascii_lowercase();
        const KNOWN: &[&str] = &[
            "py", "pyw", "js", "mjs", "cjs", "jsx", "ts", "tsx", "go", "rs", "rlib", "rb", "php",
            "pl", "lua", "jl", "swift", "kt", "java", "scala", "hs", "c", "h", "cpp", "cc",
            "hpp", "cs", "fs", "ex", "exs", "sh", "bash", "zsh", "ml", "clj", "ps1",
        ];
        if KNOWN.contains(&e.as_str()) {
            return true;
        }
    }
    false
}

pub fn resolve_in_path(name: &str) -> Option<PathBuf> {
    let candidate = Path::new(name);
    if name.contains('/') || name.contains('\\') {
        if is_executable_file(candidate) {
            return Some(candidate.to_path_buf());
        } else {
            return None;
        }
    }
    let path_env = std::env::var_os("PATH")?;
    for dir in std::env::split_paths(&path_env) {
        if dir.as_os_str().is_empty() {
            continue;
        }
        let p = dir.join(name);
        if is_executable_file(&p) {
            return Some(p);
        }
    }
    None
}

pub fn is_executable_file(path: &Path) -> bool {
    let Ok(meta) = std::fs::metadata(path) else {
        return false;
    };
    if !meta.is_file() {
        return false;
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        meta.permissions().mode() & 0o111 != 0
    }
    #[cfg(not(unix))]
    {
        true
    }
}

pub fn resolve_first(candidates: &[&str]) -> PathBuf {
    for c in candidates {
        if let Some(p) = resolve_in_path(c) {
            return p;
        }
    }
    PathBuf::from(candidates.first().copied().unwrap_or_default())
}

pub fn which_first(candidates: &[&str]) -> Option<PathBuf> {
    candidates.iter().find_map(|c| resolve_in_path(c))
}
RS"}

