            anyhow!(
                "language '{}' not supported. Available: {}",
                raw.trim().to_ascii_lowercase(),
                AVAILABLE
            )
        })
    }

    pub fn from_extension(ext: &str) -> Option<Language> {
        let e = ext.to_ascii_lowercase();
        let lang = match e.as_str() {
            "sh" | "bash" | "zsh" => Language::Bash,
