use crate::language::Language;

fn any_line<F: Fn(&str) -> bool>(code: &str, f: F) -> bool {
    code.lines().any(|l| f(l.trim_start()))
}

fn line_starts(code: &str, prefix: &str) -> bool {
    any_line(code, |l| l.starts_with(prefix))
}

pub fn detect_language(code: &str) -> Language {
    // Shebangs that are recognised explicitly.
    if code.contains("#!/bin/bash") || code.contains("#!/bin/sh") {
        return Language::Bash;
    }
    if code.contains("#!/usr/bin/perl") {
        return Language::Perl;
    }
    if code.contains("<?php") {
        return Language::Php;
    }

    // Strong compiled-language signatures.
    if code.contains("pub fn main()") {
        return Language::Zig;
    }
    if code.contains("package main") || code.contains("import \"fmt\"") {
        return Language::Go;
    }
    if code.contains("fn main()") || code.contains("use std::") {
        return Language::Rust;
    }
    if has_public_class(code) {
        return Language::Java;
    }
    if code.contains("fun main(") {
        return Language::Kotlin;
    }
    if code.contains("void main()") || code.contains("Future<void> main()") {
        return Language::Dart;
    }
    if code.contains("#include <") || code.contains("std::") || code.contains("using namespace std") {
        return Language::Cpp;
    }

    // JavaScript-ish signatures.  `import 'x'` is deliberately checked before
    // Python's bare-import rule (matching observed behaviour for Dart code).
    if code.contains("console.log") || code.contains("module.exports") {
        return Language::JavaScript;
    }
    if code.contains("import '") || code.contains("import \"") {
        // Go's canonical import was handled above only for fmt; other quoted
        // imports were observed to fall through to JavaScript.
        return Language::JavaScript;
    }
    if has_js_function(code) {
        return Language::JavaScript;
    }
    if is_typescript(code) {
        return Language::TypeScript;
    }
    if code.contains("enum ") && code.contains('{') {
        return Language::Crystal;
    }

    // Nim's distinctive `proc .... =` / typed var forms.
    if is_nim(code) {
        return Language::Nim;
    }

    // Package with a dotted name (and no Java `public class`) was Groovy.
    if is_groovy_package(code) {
        return Language::Groovy;
    }

    // Elixir before Ruby (IO.puts would otherwise look Ruby-ish).
    if code.contains("IO.puts") || code.contains("IO.inspect") || code.contains("defmodule ") {
        return Language::Elixir;
    }

    // Ruby: module declarations win over Haskell's `module ... where`.
    if is_ruby(code) {
        return Language::Ruby;
    }

    // R signatures (`require(` is R here, not Node/CommonJS).
    if code.contains("library(") || code.contains("require(") || code.contains(" <-") {
        return Language::R;
    }
    if code.trim_start().starts_with("#include") || code.trim_start().starts_with("#import") {
        // Observed quirk: a bare preprocessor line without <> falls to R.
        return Language::R;
    }

    // Haskell.
    if code.contains("main =") || is_haskell_let(code) {
        return Language::Haskell;
    }

    // Perl before Python/Lua `print` handling.
    if is_perl(code) {
        return Language::Perl;
    }

    // Groovy/Julia println forms.
    if line_starts(code, "println ") || line_starts(code, "println\"") || line_starts(code, "println'") {
        return Language::Groovy;
    }
    if code.contains("println(") {
        return Language::Julia;
    }

    // Lua function form without a parenthesised parameter list.
    if has_lua_function(code) {
        return Language::Lua;
    }

    // Python-looking declarations/imports take precedence over Lua's
    // generic `print(` and over C#'s `using System` when a class is present.
    if is_python(code) {
        return Language::Python;
    }
    if code.contains("print(") {
        return Language::Lua;
    }

    // C#.
    if code.contains("using System") || is_csharp_namespace(code) {
        return Language::CSharp;
    }

    // Echo: quoted echo is PHP, plain echo / export is shell.
    if is_php_echo(code) {
        return Language::Php;
    }
    if is_bash/code) {
        return Language::Bash;
    }

    Language::Python
}

fn is_bash(code: &str) -> bool {
    any_line(code, |l| {
        if let Some(rest) = l.strip_prefix("echo ") {
            !rest.starts_with('"') && !rest.starts_with('\'')
        } else if l.starts_with("export ") {
            true
        } else {
            false
        }
    })
}

fn has_public_class(code: &str) -> bool {
    let needle = "public class ";
    let mut from = 0;
    while let Some(pos) = code[from..].find(needle) {
        let rest = &code[from + pos + needle.len()..];
        if rest.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_') {
            return true;
        }
        from += pos + needle.len();
    }
    false
}

fn has_js_function(code: &str) -> bool {
    let mut from = 0;
    while let Some(pos) = code[from..].find("function") {
        let rest = &code[from + pos + "function".len()..];
        // `function name(` or `function(` is JS; plain `function name` is Lua.
        let rest = rest.trim_start();
        let after_name = if rest.starts_with('(') {
            Some(rest)
        } else {
            let mut parts = rest.splitn(2, |c: char| c.is_whitespace() || c == '(');
            let _name = parts.next();
            parts.next().map(|_| &rest[rest.find('(').unwrap_or(rest.len())..])
        };
        if after_name.is_some_and(|r| r.starts_with('(')) {
            return true;
        }
        from += pos + "function".len();
    }
    false
}

fn has_lua_function(code: &str) -> bool {
    any_line(code, |l| {
        if let Some(rest) = l.strip_prefix("function ") {
            // Lua form seen in probes has a name but no '(' on the line.
            !rest.trim().is_empty() && !rest.contains('(')
        } else {
            false
        }
    })
}

fn is_typescript(code: &str) -> bool {
    (code.contains("interface ") && code.contains('{'))
        || (code.contains("type ") && code.contains('='))
}

fn is_nim(code: &str) -> bool {
    any_line(code, |l| {
        (l.starts_with("proc ") && l.contains('='))
            || (l.starts_with("var ") && l.contains(':'))
    })
}

fn is_groovy_package(code: &str) -> bool {
    any_line(code, |l| {
        if let Some(rest) = l.strip_prefix("package ") {
            rest.trim().contains('.')
        } else {
            false
        }
    })
}

fn is_ruby(code: &str) -> bool {
    if code.contains("require '") || code.contains("require \"") {
        return true;
    }
    any_line(code, |l| {
        if let Some(rest) = l.strip_prefix("puts ") {
            rest.starts_with('"') || rest.starts_with('\'')
        } else if l.starts_with("puts(") {
            true
        } else if let Some(rest) = l.strip_prefix("module ") {
            rest.chars().next().is_some_and(|c| c.is_ascii_alphabetic())
        } else {
            false
        }
    })
}

fn is_haskell_let(code: &str) -> bool {
    any_line(code, |l| l.starts_with("let ") && l.contains('='))
}

fn is_perl(code: &str) -> bool {
    if code.contains("use strict") || code.contains("use warnings") {
        return true;
    }
    any_line(code, |l| {
        if let Some(rest) = l.strip_prefix("print ") {
            rest.starts_with('"') || rest.starts_with('\'')
        } else if l.starts_with("my $") || l.starts_with("our $") {
            true
        } else if let Some(rest) = l.strip_prefix("sub ") {
            rest.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
        } else {
            false
        }
    })
}

fn is_python(code: &str) -> bool {
    any_line(code, |l| {
        if let Some(rest) = l.strip_prefix("import ") {
            rest.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
        } else if l.starts_with("from ") && l.contains(" import ") {
            true
        } else if l.starts_with("def ") || l.starts_with("class ") || l.starts_with("async def ") {
            true
        } else {
            false
        }
    }) || code.contains("class ")
}

fn is_csharp_namespace(code: &str) -> bool {
    code.contains("namespace ") && code.contains('{')
}

fn is_php_echo(code: &str) -> bool {
    any_line(code, |l| {
        if let Some(rest) = l.strip_prefix("echo ") {
            rest.starts_with('"') || rest.starts_with('\'')
        } else {
            false
        }
    })
}
