fn has_public_class(code: &str) -> bool {
    let needle = "public class ";
    let mut from = 0;
    while let Some(pos) = code[from..].find(needle) {
        let rest = &code[from + pos + needle.len()..];
        if rest.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_') {
            return true;
        }
        from += pos + needle.len();
    }
    false
}

fn has_js_function(code: &str) -> bool {
    let mut from = 0;
    while let Some(pos) = code[from..].find("function") {
        let rest = &code[from + pos + "function".len()..];
        // `function name(` or `function(` is JS; plain `function name` is Lua.
        let rest = rest.trim_start();
        let after_name = if rest.starts_with('(') {
            Some(rest)
        } else {
            let mut parts = rest.splitn(2, |c: char| c.is_whitespace() || c == '(');
            let _name = parts.next();
            parts.next().map(|_| &rest[rest.find('(').unwrap_or(rest.len())..])
        };
        if after_name.is_some_and(|r| r.starts_with('(')) {
            return true;
        }
        from += pos + "function".len();
    }
    false
}

