pub fn make_tempdir(lang: Language) -> Result<TempDir> {
    let prefix = format!("run-{}", lang.id());
    tempfile::Builder::new()
        .prefix(&prefix)
        .tempdir()
        .with_context(|| tempdir_ctx(lang).to_string())
}

fn status_cmd(cmd: &mut Command) -> Result<ExitStatus> {
    Ok(cmd.status()?)
}

fn compile_cmd(cmd: &mut Command) -> Result<ExitStatus> {
    let out = cmd.output()?;
    if !out.status.success() {
        let _ = io::stdout().write_all(&out.stdout);
        let _ = io::stderr().write_all(&out.stderr);
    }
    Ok(out.status)
}

fn set_parent_dir(cmd: &mut Command, path: &Path) {
    if let Some(parent) = path.parent() {
        cmd.current_dir(parent);
    }
}

fn run_zig_capture(cmd: &mut Command, bin: &Path, source_display: &Path) -> Result<ExitStatus> {
    cmd.stdin(Stdio::inherit());
    let out = cmd.output().with_context(|| {
        format!(
            "failed to execute {} with source {}",
            bin.display(),
            source_display.display()
        )
    })?;
    let _ = io::stdout().write_all(&out.stdout);
    if out.status.success() {
        let _ = io::stdout().write_all(&out.stderr);
    } else {
        let _ = io::stderr().write_all(&out.stderr);
    }
    Ok(out.status)
}

fn script_ctx(bin: &Path, path: &Path, source_word: &str) -> String {
    format!("failed to execute {} with {} {}", bin.display(), source_word, path.display())
}

fn run_script_status(
    bin: &Path,
    args_before: &[&str],
    script_arg: &Path,
    args_after: &[&str],
    cwd: Option<&Path>,
    ctx_path: &Path,
    source_word: &str,
) -> Result<ExitStatus> {
    let mut cmd = Command::new(bin);
    cmd.args(args_before).arg(script_arg).args(args_after);
    if let Some(c) = cwd {
        cmd.current_dir(c);
    }
    let st = cmd.status().with_context(|| script_ctx(bin, ctx_path, source_word))?;
    Ok(st)
}

// ---------- Snippet source builders ----------
pub fn c_source(code: &str) -> String {
    if code.contains("#include") || code.contains("main(") {
        code.to_string()
    } else {
        let body = indent_lines(code, "    ", true);
        if body.is_empty() {
            "#include <stdio.h>\n\nint main(void)\n{\n    return 0;\n}\n".to_string()
        } else {
            format!("#include <stdio.h>\n\nint main(void)\n{{\n{}\n    return 0;\n}}\n", body)
        }
    }
}

pub fn dart_source(code: &str) -> String {
    if code.contains("void main") || code.contains("Future<void> main") {
        return ensure_nl(code);
    }
    let mut lines_out: Vec<String> = Vec::new();
    for line in code.lines() {
        if line.trim().is_empty() {
            lines_out.push(format!("  {}", line));
        } else {
            let te = line.trim_end();
            if te.ends_with(';') || te.ends_with('}') {
                lines_out.push(format!("  {}", line));
            } else {
                lines_out.push(format!("  {};", line));
            }
        }
    }
    if lines_out.is_empty() {
        "Future<void> main() async {\n}\n".to_string()
    } else {
        format!("Future<void> main() async {{\n{}\n}}\n", lines_out.join("\n"))
    }
}

pub fn java_source(code: &str) -> String {
    if code.contains("class ") {
        return code.to_string();
    }
    let mut header: Vec<&str> = Vec::new();
    let mut lines = code.lines().peekable();
    while let Some(&line) = lines.peek() {
        let t = line.trim_start();
        if t.starts_with("import ") || t.starts_with("package ") {
            header.push(line);
            lines.next();
        } else {
            break;
        }
    }
    let remaining: Vec<&str> = lines.collect();
    let body = remaining
        .iter()
        .map(|l| format!("        {}", l))
        .collect::<Vec<_>>()
        .join("\n");
    let class_block = if body.is_empty() {
        "public class Main {\n    public static void main(String[] args) throws Exception {\n    }\n}\n".to_string()
    } else {
        format!(
            "public class Main {{\n    public static void main(String[] args) throws Exception {{\n{}\n    }}\n}}\n",
            body
        )
    };
    if header.is_empty() {
        class_block
    } else {
        format!("{}\n\n{}", header.join("\n"), class_block)
    }
}

pub fn kotlin_source(code: &str) -> String {
    if code.contains("fun main") {
        code.to_string()
    } else {
        let body = indent_lines(code, "    ", false);
        if body.is_empty() {
            "fun main() {\n}\n".to_string()
        } else {
            format!("fun main() {{\n{}\n}}\n", body)
        }
    }
}

pub fn php_source(code: &str) -> String {
    if code.starts_with("<?php") {
        ensure_nl(code)
    } else {
        ensure_nl(&format!("<?php\n{}", code))
    }
}

pub fn zig_source(code: &str) -> String {
    if code.contains("pub fn main") || code.trim().is_empty() {
        ensure_nl(code)
    } else {
        let body = indent_lines(code, "    ", false);
        format!(
            "const std = @import(\"std\");\n\npub fn main() !void {{\n{}\n}}\n",
            body
        )
    }
}

pub fn groovy_transform(code: &str) -> String {
    let Some(last) = code.lines().rev().find(|l| !l.trim().is_empty()) else {
        return code.to_string();
    };
    // Strip a trailing // comment for the expression check / argument.
    let clean_full = match last.split_once("//") {
        Some((before, _)) => before,
        None => last,
    };
    let clean = clean_full.trim();
    if clean.is_empty() {
        return code.to_string();
    }
    let starts_print = clean.starts_with("println")
        || clean.starts_with("print ")
        || clean.starts_with("print(")
        || clean.starts_with("print (");
    if starts_print {
        return code.to_string();
    }
    // A last line with an internal semicolon is not a single expression.
    let without_trailing_semi = clean.strip_suffix(';').unwrap_or(clean);
    if without_trailing_semi.contains(';') {
        return code.to_string();
    }
    format!("{}\nprintln({});\n", code.trim_end_matches('\n'), clean)
    // Note: for code already ending in blank lines the original preserves
    // them; trim_end_matches above would collapse them. Handle that below
    // by reconstructing in the common path used by callers via a special
    // case in groovy_transform_preserve.
}

pub fn groovy_transform_preserve(code: &str) -> String {
    let Some(last) = code.lines().rev().find(|l| !l.trim().is_empty()) else {
        return code.to_string();
    };
    let clean_full = match last.split_once("//") {
        Some((before, _)) => before,
        None => last,
    };
    let clean = clean_full.trim();
    if clean.is_empty() {
        return code.to_string();
    }
    let starts_print = clean.starts_with("println")
        || clean.starts_with("print ")
        || clean.starts_with("print(")
        || clean.starts_with("print (");
    if starts_print {
        return code.to_string();
    }
    let without_trailing_semi = clean.strip_suffix(';').unwrap_or(clean);
    if without_trailing_semi.contains(';') {
        return code.to_string();
    }
    if code.ends_with('\n') {
        format!("{}println({});\n", code, clean)
    } else {
        format!("{}\nprintln({});\n", code, clean)
    }
}

// ---------- Code execution ----------
pub fn run_code_status(ctx: &Ctx, lang: Language, code: &str, tools: &Tools) -> Result<ExitStatus> {
    let bin = &tools.primary;
    match lang {
        Language::Bash => status_cmd(Command::new(bin).arg("-c").arg(code)),
        Language::Python => status_cmd(Command::new(bin).arg("-c").arg(code)),
        Language::JavaScript => status_cmd(Command::new(bin).arg("-e").arg(code)),
        Language::Ruby => status_cmd(Command::new(bin).arg("-e").arg(code)),
        Language::Groovy => {
            let transformed = groovy_transform_preserve(code);
            status_cmd(Command::new(bin).arg("-e").arg(transformed))
        }
        Language::C | Language::Cpp => {
            let dir = make_tempdir(lang)?;
            let (src_name, out_name, source, flags): (&str, &str, String, &[&str]) = if lang == Language::C {
                ("main.c", "run_c_binary", c_source(code), &["-std=c11", "-O0", "-Wall", "-Wextra"][..])
            } else {
                ("main.cpp", "run_cpp_binary", code.to_string(), &["-std=c++17", "-O0", "-Wall", "-Wextra"][..])
            };
            let src = dir.path().join(src_name);
            fs::write(&src, source)?;
            let out_bin = dir.path().join(out_name);
            let st = compile_cmd(Command::new(bin).arg(&src).args(flags).arg("-o").arg(&out_bin))?;
            if !st.success() {
                return Ok(st);
            }
            status_cmd(&mut Command::new(&out_bin))
        }
        Language::Rust => {
            let dir = make_tempdir(lang)?;
            let src = dir.path().join("main.rs");
            fs::write(&src, code)?;
            let out_bin = dir.path().join("run_rust_binary");
            let st = compile_cmd(
                Command::new(bin)
                    .args(["--color=never", "--edition=2021", "--crate-name", "run_snippet"])
                    .arg(&src)
                    .arg("-o")
                    .arg(&out_bin),
            )?;
            if !st.success() {
                return Ok(st);
            }
            status_cmd(&mut Command::new(&out_bin))
        }
        Language::Java => run_java_snippet(tools, code),
        Language::Kotlin => {
            let dir = make_tempdir(lang)?;
            let src = dir.path().join("Main.kt");
            fs::write(&src, kotlin_source(code))?;
            let jar = dir.path().join("snippet.jar");
            let st = compile_cmd(Command::new(bin).arg(&src).args(["-include-runtime", "-d"]).arg(&jar))?;
            if !st.success() {
                return Ok(st);
            }
            let java = require_java_runtime(true)?;
            status_cmd(Command::new(java).arg("-jar").arg(&jar))
        }
        Language::CSharp => run_csharp(ctx, tools, CSharpInput::Code(code.to_string())),
        Language::TypeScript => {
            let mut tmp = tempfile::NamedTempFile::new()
                .with_context(|| "failed to create temporary TypeScript file".to_string())?;
            tmp.write_all(ensure_nl(code).as_bytes())?;
            // Keep file alive until process finishes: into_temp_path keeps path.
            let path = tmp.into_temp_path();
            let st = status_cmd(
                Command::new(bin)
                    .args(["run", "--quiet", "--no-check", "--ext", "ts"])
                    .arg(&path),
            );
            let _ = path.close();
            st
        }
        Language::Go => {
            let dir = make_tempdir(lang)?;
            fs::write(dir.path().join("main.go"), ensure_nl(code))?;
            let mut cmd = Command::new(bin);
            cmd.arg("run").arg("main.go").current_dir(dir.path());
            cmd.status().with_context(|| format!("failed to invoke {} to run main.go", bin.display()))
                .map_err(anyhow::Error::from)
        }
        Language::Dart => {
            let dir = make_tempdir(lang)?;
            fs::write(dir.path().join("main.dart"), dart_source(code))?;
            let mut cmd = Command::new(bin);
            cmd.args(["run", "--enable-asserts", "main.dart"]).current_dir(dir.path());
            cmd.status().with_context(|| format!("failed to invoke {} to run main.dart", bin.display()))
                .map_err(anyhow::Error::from)
        }
        Language::Zig => run_zig_snippet_source(tools, &zig_source(code)),
        Language::Nim => {
            let dir = make_tempdir(lang)?;
            let src = dir.path().join("snippet.nim");
            fs::write(&src, ensure_nl(code))?;
            status_cmd(
                Command::new(bin)
                    .arg("r")
                    .arg(&src)
                    .args(["--colors:off", "--hints:off", "--verbosity:0"])
                    .current_dir(dir.path()),
            )
        }
        Language::Crystal => {
            let dir = make_tempdir(lang)?;
            let src = dir.path().join("snippet.cr");
            fs::write(&src, ensure_nl(code))?;
            run_script_status(bin, &["run"], &src, &["--no-color"], Some(dir.path()), &src, "source")
        }
        Language::Elixir => snippet_simple(lang, tools, "snippet.exs", &ensure_nl(code), &["--no-color"], &[], true, "script"),
        Language::Haskell => snippet_simple(lang, tools, "snippet.hs", &ensure_nl(code), &[], &[], true, "script"),
        Language::Julia => snippet_simple(lang, tools, "snippet.jl", &ensure_nl(code), &["--color=no", "--quiet"], &[], true, "script"),
        Language::Lua => snippet_simple(lang, tools, "snippet.lua", &ensure_nl(code), &[], &[], true, "script"),
        Language::Perl => snippet_simple(lang, tools, "snippet.pl", &ensure_nl(code), &[], &[], true, "script"),
        Language::Php => snippet_simple(lang, tools, "snippet.php", &php_source(code), &[], &[], true, "script"),
        Language::Swift => snippet_simple(lang, tools, "snippet.swift", &ensure_nl(code), &[], &[], true, "script"),
        Language::R => {
            let dir = make_tempdir(lang)?;
            let src = dir.path().join("snippet.R");
            fs::write(&src, ensure_nl(code))?;
            status_cmd(Command::new(bin).arg("--vanilla").arg(&src))
        }
    }
}

fn snippet_simple(
    lang: Language,
    tools: &Tools,
    filename: &str,
    source: &str,
    before: &[&str],
    after: &[&str],
    cwd_temp: bool,
    word: &str,
) -> Result<ExitStatus> {
    let dir = make_tempdir(lang)?;
    let src = dir.path().join(filename);
    fs::write(&src, source)?;
    run_script_status(
        &tools.primary,
        before,
        &src,
        after,
        if cwd_temp { Some(dir.path()) } else { None },
        &src,
        word,
    )
}

fn require_java_runtime(kotlin: bool) -> Result<PathBuf> {
    if let Some(p) = which_first(&["java"]) {
        Ok(p)
    } else if kotlin {
        Err(anyhow!("Kotlin execution requires a `java` runtime. Install a JDK and ensure `java` is on your PATH."))
    } else {
        Err(anyhow!("Java support requires the `java` runtime. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH."))
    }
}

pub fn run_java_snippet(tools: &Tools, code: &str) -> Result<ExitStatus> {
    // tools.primary is javac (checked).
    let dir = make_tempdir(Language::Java)?;
    let src = dir.path().join("Main.java");
    fs::write(&src, java_source(code))?;
    let st = compile_cmd(Command::new(&tools.primary).arg("-d").arg(dir.path()).arg(&src))?;
    if !st.success() {
        return Ok(st);
    }
    let java = require_java_runtime(false)?;
    status_cmd(Command::new(java).arg("-cp").arg(dir.path()).arg("Main"))
}

enum CSharpInput {
    Code(String),
    File(PathBuf),
}

fn csharp_project(ctx: &Ctx) -> String {
    let fw = ctx.dotnet_framework.as_deref().unwrap_or("net8.0");
    format!(
        "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <PropertyGroup>\n    <OutputType>Exe</OutputType>\n    <TargetFramework>{}</TargetFramework>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <Nullable>disable</Nullable>\n        <NoWarn>CS0219;CS8321</NoWarn>\n  </PropertyGroup>\n</Project>\n",
        fw
    )
}

fn run_csharp(ctx: &Ctx, tools: &Tools, input: CSharpInput) -> Result<ExitStatus> {
    let dir = make_tempdir(Language::CSharp)?;
    let proj = dir.path().join("Run.csproj");
    fs::write(&proj, csharp_project(ctx))?;
    let prog = dir.path().join("Program.cs");
    match input {
        CSharpInput::Code(code) => {
            fs::write(&prog, ensure_nl(&code))?;
        }
        CSharpInput::File(ref p) => {
            fs::copy(p, &prog).with_context(|| {
                format!("failed to copy C# source from {} to {}", p.display(), prog.display())
            })?;
        }
    }
    status_cmd(
        Command::new(&tools.primary)
            .arg("run")
            .arg("--project")
            .arg(&proj)
            .arg("--nologo")
            .current_dir(dir.path()),
    )
}

fn run_zig_snippet_source(tools: &Tools, source: &str) -> Result<ExitStatus> {
    let dir = make_tempdir(Language::Zig)?;
    let src = dir.path().join("snippet.zig");
    fs::write(&src, source)?;
    let mut cmd = Command::new(&tools.primary);
    cmd.arg("run").arg(&src).current_dir(dir.path());
    run_zig_capture(&mut cmd, &tools.primary, &src)
}

// ---------- File execution ----------
pub fn run_file_status(ctx: &Ctx, lang: Language, path: &Path, tools: &Tools) -> Result<ExitStatus> {
    let bin = &tools.primary;
    match lang {
        Language::Bash | Language::Python | Language::JavaScript | Language::Ruby | Language::Groovy => {
            status_cmd(Command::new(bin).arg(path))
        }
        Language::R => status_cmd(Command::new(bin).arg("--vanilla").arg(path)),
        Language::TypeScript => status_cmd(
            Command::new(bin)
                .args(["run", "--quiet", "--no-check", "--ext", "ts"])
                .arg(path),
        ),
        Language::C | Language::Cpp => {
            let dir = make_tempdir(lang)?;
            let (src_name, out_name, flags, copy_label): (&str, &str, &[&str], &str) = if lang == Language::C {
                ("main.c", "run_c_binary", &["-std=c11", "-O0", "-Wall", "-Wextra"][..], "C")
            } else {
                ("main.cpp", "run_cpp_binary", &["-std=c++17", "-O0", "-Wall", "-Wextra"][..], "C++")
            };
            let src = dir.path().join(src_name);
            fs::copy(path, &src).with_context(|| {
                format!("failed to copy {} source from {} to {}", copy_label, path.display(), src.display())
            })?;
            let out_bin = dir.path().join(out_name);
            let st = compile_cmd(Command::new(bin).arg(&src).args(flags).arg("-o").arg(&out_bin))?;
            if !st.success() {
                return Ok(st);
            }
            status_cmd(&mut Command::new(&out_bin))
        }
        Language::Rust => {
            let dir = make_tempdir(lang)?;
            let out_bin = dir.path().join("run_rust_binary");
            let st = compile_cmd(
                Command::new(bin)
                    .args(["--color=never", "--edition=2021", "--crate-name", "run_snippet"])
                    .arg(path)
                    .arg("-o")
                    .arg(&out_bin),
            )?;
            if !st.success() {
                return Ok(st);
            }
            status_cmd(&mut Command::new(&out_bin))
        }
        Language::Java => {
            let Some(file_name) = path.file_name() else {
                return Err(anyhow!("invalid Java source path"));
            };
            let dir = make_tempdir(lang)?;
            let dest = dir.path().join(file_name);
            fs::copy(path, &dest).with_context(|| {
                format!("failed to copy Java source from {} to {}", path.display(), dest.display())
            })?;
            let st = compile_cmd(Command::new(bin).arg("-d").arg(dir.path()).arg(&dest))?;
            if !st.success() {
                return Ok(st);
            }
            let java = require_java_runtime(false)?;
            let class_name = path
                .file_stem()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_default();
            status_cmd(Command::new(java).arg("-cp").arg(dir.path()).arg(class_name))
        }
        Language::Kotlin => {
            let Some(file_name) = path.file_name() else {
                return Err(anyhow!("invalid Kotlin source path"));
            };
            let dir = make_tempdir(lang)?;
            let dest = dir.path().join(file_name);
            fs::copy(path, &dest).with_context(|| {
                format!("failed to copy Kotlin source from {} to {}", path.display(), dest.display())
            })?;
            let jar = dir.path().join("snippet.jar");
            let st = compile_cmd(Command::new(bin).arg(&dest).args(["-include-runtime", "-d"]).arg(&jar))?;
            if !st.success() {
                return Ok(st);
            }
            let java = require_java_runtime(true)?;
            status_cmd(Command::new(java).arg("-jar").arg(&jar))
        }
        Language::CSharp => run_csharp(ctx, tools, CSharpInput::File(path.to_path_buf())),
        Language::Go => {
            let mut cmd = Command::new(bin);
            cmd.arg("run");
            set_parent_dir(&mut cmd, path);
            if let Some(name) = path.file_name() {
                cmd.arg(name);
            } else {
                cmd.arg(path);
            }
            cmd.status()
                .with_context(|| format!("failed to invoke {} to run {}", bin.display(), path.display()))
                .map_err(anyhow::Error::from)
        }
        Language::Dart => {
            let mut cmd = Command::new(bin);
            cmd.args(["run", "--enable-asserts"]);
            set_parent_dir(&mut cmd, path);
            if let Some(name) = path.file_name() {
                cmd.arg(name);
            } else {
                cmd.arg(path);
            }
            cmd.status()
                .with_context(|| format!("failed to invoke {} to run {}", bin.display(), path.display()))
                .map_err(anyhow::Error::from)
        }
        Language::Crystal => {
            let mut cmd = Command::new(bin);
            cmd.arg("run").arg(path).arg("--no-color");
            set_parent_dir(&mut cmd, path);
            cmd.status()
                .with_context(|| script_ctx(bin, path, "source"))
                .map_err(anyhow::Error::from)
        }
        Language::Elixir => parent_script(bin, &["--no-color"], path, &[], "script"),
        Language::Haskell => parent_script(bin, &[], path, &[], "script"),
        Language::Julia => parent_script(bin, &["--color=no", "--quiet"], path, &[], "script"),
        Language::Lua => parent_script(bin, &[], path, &[], "script"),
        Language::Perl => parent_script(bin, &[], path, &[], "script"),
        Language::Php => parent_script(bin, &[], path, &[], "script"),
        Language::Swift => parent_script(bin, &[], path, &[], "script"),
        Language::Nim => {
            if path.extension().and_then(OsStr::to_str) == Some("nim") {
                let mut cmd = Command::new(bin);
                cmd.arg("r").arg(path).args(["--colors:off", "--hints:off", "--verbosity:0"]);
                set_parent_dir(&mut cmd, path);
                cmd.status()
                    .with_context(|| script_ctx(bin, path, "source"))
                    .map_err(anyhow::Error::from)
            } else {
                let code = fs::read_to_string(path)?;
                // Re-use snippet execution (no extra transform for Nim).
                run_code_status(ctx, lang, &code, tools)
            }
        }
        Language::Zig => {
            if path.extension().and_then(OsStr::to_str) == Some("zig") {
                let mut cmd = Command::new(bin);
                cmd.arg("run").arg(path);
                set_parent_dir(&mut cmd, path);
                run_zig_capture(&mut cmd, bin, path)
            } else {
                let code = fs::read_to_string(path)?;
                run_zig_snippet_source(tools, &ensure_nl(&code))
            }
        }
    }
}

fn parent_script(bin: &Path, before: &[&str], path: &Path, after: &[&str], word: &str) -> Result<ExitStatus> {
    let mut cmd = Command::new(bin);
    cmd.args(before).arg(path).args(after);
    set_parent_dir(&mut cmd, path);
    cmd.status()
        .with_context(|| script_ctx(bin, path, word))
        .map_err(anyhow::Error::from)
}

// ---------- Stdin execution ----------
pub fn run_stdin_status(ctx: &Ctx, lang: Language, code: &str, tools: &Tools) -> Result<ExitStatus> {
    match lang {
        Language::Python | Language::JavaScript | Language::Ruby | Language::Bash | Language::TypeScript => {
            let bin = &tools.primary;
            let mut cmd = Command::new(bin);
            match lang {
                Language::Bash => {}
                Language::TypeScript => {
                    cmd.args(["run", "--quiet", "--no-check", "--ext", "ts", "-"]);
                }
                _ => {
                    cmd.arg("-");
                }
            }
            cmd.stdin(Stdio::piped());
            let label = match lang {
                Language::Python => "python3",
                Language::JavaScript => "node",
                Language::Ruby => "ruby",
                Language::Bash => "bash",
                _ => "deno",
            };
            let mut child = cmd.spawn().with_context(|| {
                if lang == Language::TypeScript {
                    format!("failed to start Deno for stdin execution because 'deno' was not found in PATH. {}", DENO_INSTALL)
                } else {
                    format!("failed to start {} for stdin execution", label)
                }
            })?;
            if let Some(mut stdin) = child.stdin.take() {
                if lang == Language::Python {
                    let _ = stdin.write_all(code.as_bytes());
                } else {
                    let data = ensure_nl(code);
                    let _ = stdin.write_all(data.as_bytes());
                }
            }
            Ok(child.wait()?)
        }
        Language::Groovy => {
            let transformed = groovy_transform_preserve(code);
            let mut tmp = tempfile::Builder::new()
                .prefix("run-groovy-stdin")
                .suffix(".groovy")
                .tempfile()
                .with_context(|| "failed to create temporary Groovy script for stdin input".to_string())?;
            tmp.write_all(ensure_nl(&transformed).as_bytes())?;
            let path = tmp.into_temp_path();
            let st = status_cmd(Command::new(&tools.primary).arg(&path));
            let _ = path.close();
            st
        }
        _ => run_code_status(ctx, lang, code, tools),
    }
}

pub fn execute_code_cli(ctx: &Ctx, lang: Language, code: &str) -> Result<()> {
    let tools = preflight(ctx, lang, Mode::Inline)?;
    let st = run_code_status(ctx, lang, code, &tools)?;
    exit_with_status(st)
}

pub fn execute_file_cli(ctx: &Ctx, lang: Language, path: &Path) -> Result<()> {
    let tools = preflight(ctx, lang, Mode::File)?;
    let st = run_file_status(ctx, lang, path, &tools)?;
    exit_with_status(st)
}

pub fn execute_stdin_cli(ctx: &Ctx, lang: Language, code: &str) -> Result<()> {
    let tools = preflight(ctx, lang, Mode::Stdin)?;
    let st = run_stdin_status(ctx, lang, code, &tools)?;
    exit_with_status(st)
}
RS"}

