use crate::language::{resolve_first, which_first, Language};

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    Inline,
    File,
    Stdin,
}

#[derive(Clone)]
pub struct Tools {
    pub primary: PathBuf,
    pub secondary: Option<PathBuf>,
}

#[derive(Clone)]
pub struct Ctx {
    pub dotnet_framework: Option<String>,
}

pub fn detect_dotnet_framework() -> Option<String> {
    let bin = resolve_first(&["dotnet"]);
    let output = Command::new(&bin).arg("--list-sdks").output().ok()?;
    let text = String::from_utf8_lossy(&output.stdout);
    let mut best: Option<(u64, u64)> = None;
    for line in text.lines() {
        let Some(first) = line.split_whitespace().next() else { continue };
        let mut parts = first.split('.');
        let Some(maj) = parts.next().and_then(|p| p.parse::<u64>().ok()) else { continue };
        let Some(min) = parts.next().and_then(|p| p.parse::<u64>().ok()) else { continue };
        let v = (maj, min);
        if best.is_none_or(|b| v > b) {
            best = Some(v);
        }
    }
    best.map(|(maj, min)| format!("net{}.{}", maj, min))
}

const DENO_INSTALL: &str = "Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.";

