    // Explicit --code
    if let Some(code) = &cli.code {
        let mut lang_raw = cli.lang.clone();
        if !cli.args.is_empty() {
            if lang_raw.is_none()
                && cli.args.len() == 1
                && Language::parse(&cli.args[0]).is_some()
            {
                lang_raw = Some(cli.args[0].clone());
            } else {
                return Err(anyhow!("Unexpected positional arguments after specifying --code"));
            }
        }
        return Ok(Payload::Code { lang_raw, code: code.clone() });
    }

    let mut args = cli.args.clone();
    let mut lang_raw = cli.lang.clone();
    if lang_raw.is_none() {
        if let Some(first) = args.first() {
            if Language::parse(first).is_some() {
                lang_raw = Some(args.remove(0));
            }
        }
    }
    if let Some(first) = args.first().cloned() {
        if first == "--code" || first == "-c" {
            if args.len() < 2 {
                return Err(anyhow!("--code/--inline requires a code argument"));
            }
            let code = args[1..].join(" ");
            return Ok(Payload::Code { lang_raw, code });
        }
        if first == "--file" || first == "-f" {
            if args.len() < 2 {
                return Err(anyhow!("--file requires a path argument"));
            }
            if args.len() > 2 {
                return Err(anyhow!("Unexpected positional arguments after specifying --file"));
            }
            return Ok(Payload::File { lang_raw, path: PathBuf::from(&args[1]) });
        }
    }
    if args.is_empty() {
        if std::io::stdin().is_terminal() {
            return Ok(Payload::Repl { lang_raw });
        }
        let mut buf = String::new();
        std::io::stdin()
            .read_to_string(&mut buf)
            .with_context(|| "failed to materialize execution payload".to_string())?;
        return Ok(Payload::Stdin { lang_raw, code: buf });
    }
    if args.len() == 1 && looks_like_file(&args[0]) {
        return Ok(Payload::File { lang_raw, path: PathBuf::from(&args[0]) });
    }
    Ok(Payload::Code { lang_raw, code: args.join(" ") })
