    let lang_raw = match &payload {
        Payload::Code { lang_raw, .. }
        | Payload::File { lang_raw, .. }
        | Payload::Stdin { lang_raw, .. }
        | Payload::Repl { lang_raw } => lang_raw.clone(),
    };
    let lang = resolve_language(&lang_raw, &payload, cli.no_detect)?;

    match payload {
        Payload::Code { code, .. } => runner::execute_code_cli(&ctx, lang, &code),
        Payload::File { path, .. } => runner::execute_file_cli(&ctx, lang, &path),
        Payload::Stdin { code, .. } => runner::execute_stdin_cli(&ctx, lang, &code),
        Payload::Repl { .. } => {
            let auto_detect = lang_raw.is_none() && !cli.no_detect;
            repl::run_repl(&ctx, lang, auto_detect)
        }
    }
}
