{"command":"cat > src/editor.rs <<'RS'
use anyhow::Result;
use crossterm::event::{self, Event, KeyCode, KeyEventKind, KeyModifiers};
use crossterm::terminal;
use std::fs;
use std::io::{self, Write};
use std::path::PathBuf;
use unicode_width::UnicodeWidthChar;

const MAX_HISTORY: usize = 100;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ReadOutcome {
    Line(String),
    Interrupted,
    Eof,
}

pub struct Editor {
    history: Vec<String>,
    history_path: Option<PathBuf>,
}

fn home_dir() -> Option<PathBuf> {
    if let Some(h) = std::env::var_os("HOME") {
        if !h.is_empty() {
            return Some(PathBuf::from(h));
        }
    }
    #[cfg(unix)]
    unsafe {
        let uid = libc::getuid();
        let pw = libc::getpwuid(uid);
        if !pw.is_null() && !(*pw).pw_dir.is_null() {
            let cstr = std::ffi::CStr::from_ptr((*pw).pw_dir);
            return Some(PathBuf::from(cstr.to_string_lossy().into_owned()));
        }
    }
    None
}

fn unescape_v2(line: &str) -> String {
    let mut out = String::new();
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.peek().copied() {
                Some('n') => {
                    chars.next();
                    out.push('\n');
                }
                Some('\\') => {
                    chars.next();
                    out.push('\\');
                }
                _ => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn escape_v2(entry: &str) -> String {
    let mut out = String::new();
    for c in entry.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            _ => out.push(c),
        }
    }
    out
}

impl Editor {
    pub fn new() -> Self {
        let history_path = home_dir().map(|h| h.join(".run_history"));
        let mut ed = Editor { history: Vec::new(), history_path };
        ed.load();
        ed
    }

    fn load(&mut self) {
        let Some(path) = &self.history_path else { return };
        let Ok(data) = fs::read_to_string(path) else { return };
        let mut lines = data.lines();
        let first = lines.next();
        let entries: Vec<String> = if first == Some("#V2") {
            lines.map(unescape_v2).collect()
        } else {
            let mut v = Vec::new();
            if let Some(f) = first {
                v.push(f.to_string());
            }
            v.extend(lines.map(|s| s.to_string()));
            v
        };
        for e in entries {
            self.push_history(e);
        }
    }

    fn push_history(&mut self, entry: String) {
        if entry.trim().is_empty() {
            return;
        }
        if self.history.last().is_some_and(|last| last == &entry) {
            return;
        }
        self.history.push(entry);
        if self.history.len() > MAX_HISTORY {
            let excess = self.history.len() - MAX_HISTORY;
            self.history.drain(0..excess);
        }
    }

    pub fn add_history(&mut self, entry: &str) {
        let e = entry.trim_end().to_string();
        self.push_history(e);
    }

    pub fn save_history(&self) {
        let Some(path) = &self.history_path else { return };
        let mut content = String::from("#V2\n");
        for e in &self.history {
            content.push_str(&escape_v2(e));
            content.push('\n');
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            let mut opts = fs::OpenOptions::new();
            opts.write(true).create(true).truncate(true).mode(0o600);
            if let Ok(mut f) = opts.open(path) {
                let _ = f.write_all(content.as_bytes());
                return;
            }
        }
        let _ = fs::write(path, content);
    }

    pub fn readline(&mut self, prompt: &str) -> Result<ReadOutcome> {
        let mut stdout = io::stdout().lock();
        terminal::enable_raw_mode()?;
        let res = self.readline_inner(prompt, &mut stdout);
        let _ = terminal::disable_raw_mode();
        res
    }

    fn readline_inner(&mut self, prompt: &str, out: &mut impl Write) -> Result<ReadOutcome> {
        let mut buf: Vec<char> = Vec::new();
        let mut cursor: usize = 0;
        let mut hist_idx: Option<usize> = None;
        let mut saved: Vec<char> = Vec::new();
        let mut kill_buf: Vec<char> = Vec::new();
        let mut prev_lines: usize = 1;
        let mut prev_cursor_line: usize = 0;

        write!(out, "\x1b[?2004h")?;
        draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
        out.flush()?;

        loop {
            let ev = match event::read() {
                Ok(e) => e,
                Err(_) => {
                    // Treat read failure as EOF.
                    draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                    write!(out, "\x1b[?2004l\r\n")?;
                    out.flush()?;
                    return Ok(ReadOutcome::Eof);
                }
            };
            match ev {
                Event::Paste(text) => {
                    for c in text.chars() {
                        if c == '\r' {
                            // Paste normalisation: \r\n -> \n, lone \r -> \n
                            buf.insert(cursor, '\n');
                            cursor += 1;
                        } else {
                            buf.insert(cursor, c);
                            cursor += 1;
                        }
                    }
                    // Remove a \n that resulted from \r if the source had \r\n pairs is
                    // not easily tracked; accept as-is apart from collapsing \n\n from \r\n:
                    // (handled by normal terminal paste rarely containing \r)
                    draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                    out.flush()?;
                }
                Event::Resize(_, _) => {
                    draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                    out.flush()?;
                }
                Event::Key(key) => {
                    if key.kind == KeyEventKind::Release {
                        continue;
                    }
                    let mods = key.modifiers;
                    let ctrl = mods.contains(KeyModifiers::CONTROL);
                    let alt = mods.contains(KeyModifiers::ALT);
                    match key.code {
                        KeyCode::Enter => {
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            cursor = buf.len();
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            write!(out, "\x1b[?2004l\r\n")?;
                            out.flush()?;
                            return Ok(ReadOutcome::Line(buf.iter().collect()));
                        }
                        KeyCode::Char('c') if ctrl => {
                            write!(out, "\x1b[?2004l\r\n^C\r\n")?;
                            out.flush()?;
                            return Ok(ReadOutcome::Interrupted);
                        }
                        KeyCode::Char('d') if ctrl => {
                            if buf.is_empty() {
                                draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                                write!(out, "\x1b[?2004l\r\n")?;
                                out.flush()?;
                                return Ok(ReadOutcome::Eof);
                            } else if cursor < buf.len() {
                                buf.remove(cursor);
                                draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                                out.flush()?;
                            }
                            // at end: no-op (observed)
                        }
                        KeyCode::Char('l') if ctrl => {
                            write!(out, "\x1b[H\x1b[J")?;
                            prev_lines = 1;
                            prev_cursor_line = 0;
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('a') if ctrl => {
                            cursor = 0;
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('e') if ctrl => {
                            cursor = buf.len();
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('b') if ctrl => {
                            cursor = cursor.saturating_sub(1);
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('f') if ctrl => {
                            if cursor < buf.len() { cursor += 1; }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('p') if ctrl => {
                            history_prev(&self.history, &mut buf, &mut cursor, &mut hist_idx, &mut saved);
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('n') if ctrl => {
                            history_next(&self.history, &mut buf, &mut cursor, &mut hist_idx, &mut saved);
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('k') if ctrl => {
                            if cursor < buf.len() {
                                kill_buf = buf.drain(cursor..).collect();
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('u') if ctrl => {
                            if cursor > 0 {
                                kill_buf = buf.drain(..cursor).collect();
                                cursor = 0;
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('w') if ctrl => {
                            let start = word_start_before(&buf, cursor);
                            if start < cursor {
                                kill_buf = buf.drain(start..cursor).collect();
                                cursor = start;
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('y') if ctrl => {
                            for c in kill_buf.clone() {
                                buf.insert(cursor, c);
                                cursor += 1;
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('t') if ctrl => {
                            if buf.len() >= 2 && cursor > 0 {
                                let a = if cursor == buf.len() { cursor - 2 } else { cursor - 1 };
                                buf.swap(a, a + 1);
                                if cursor < buf.len() { cursor += 1; }
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('h') if ctrl => {
                            if cursor > 0 {
                                cursor -= 1;
                                buf.remove(cursor);
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('b') if alt => {
                            cursor = word_start_before(&buf, cursor);
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('f') if alt => {
                            cursor = word_end_after(&buf, cursor);
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char('d') if alt => {
                            let end = word_end_after(&buf, cursor);
                            if end > cursor {
                                kill_buf = buf.drain(cursor..end).collect();
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Backspace if alt => {
                            let start = word_start_before(&buf, cursor);
                            if start < cursor {
                                kill_buf = buf.drain(start..cursor).collect();
                                cursor = start;
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Char(c) if !ctrl && !alt => {
                            // Enter variants arrive as KeyCode::Enter; other chars insert.
                            buf.insert(cursor, c);
                            cursor += 1;
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Backspace => {
                            if cursor > 0 {
                                cursor -= 1;
                                buf.remove(cursor);
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Delete => {
                            if cursor < buf.len() {
                                buf.remove(cursor);
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Left => {
                            if mods.contains(KeyModifiers::CONTROL) || alt {
                                cursor = word_start_before(&buf, cursor);
                            } else {
                                cursor = cursor.saturating_sub(1);
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Right => {
                            if mods.contains(KeyModifiers::CONTROL) || alt {
                                cursor = word_end_after(&buf, cursor);
                            } else if cursor < buf.len() {
                                cursor += 1;
                            }
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Home => {
                            cursor = 0;
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::End => {
                            cursor = buf.len();
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Up => {
                            history_prev(&self.history, &mut buf, &mut cursor, &mut hist_idx, &mut saved);
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Down => {
                            history_next(&self.history, &mut buf, &mut cursor, &mut hist_idx, &mut saved);
                            draw(out, prompt, &buf, cursor, &mut prev_lines, &mut prev_cursor_line)?;
                            out.flush()?;
                        }
                        KeyCode::Tab | KeyCode::BackTab => {
                            write!(out, "\x07")?;
                            out.flush()?;
                        }
                        _ => {}
                    }
                }
                _ => {}
            }
        }
    }
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn word_start_before(buf: &[char], mut cursor: usize) -> usize {
    while cursor > 0 && buf[cursor - 1].is_whitespace() {
        cursor -= 1;
    }
    if cursor > 0 && is_word_char(buf[cursor - 1]) {
        while cursor > 0 && is_word_char(buf[cursor - 1]) {
            cursor -= 1;
        }
    } else {
        while cursor > 0 && !buf[cursor - 1].is_whitespace() && !is_word_char(buf[cursor - 1]) {
            cursor -= 1;
        }
    }
    cursor
}

fn word_end_after(buf: &[char], mut cursor: usize) -> usize {
    while cursor < buf.len() && buf[cursor].is_whitespace() {
        cursor += 1;
    }
    if cursor < buf.len() && is_word_char(buf[cursor]) {
        while cursor < buf.len() && is_word_char(buf[cursor]) {
            cursor += 1;
        }
    } else {
        while cursor < buf.len() && !buf[cursor].is_whitespace() && !is_word_char(buf[cursor]) {
            cursor += 1;
        }
    }
    cursor
}

fn history_prev(
    history: &[String],
    buf: &mut Vec<char>,
    cursor: &mut usize,
    hist_idx: &mut Option<usize>,
    saved: &mut Vec<char>,
) {
    if history.is_empty() {
        return;
    }
    match hist_idx {
        None => {
            *saved = buf.clone();
            let idx = history.len() - 1;
            *hist_idx = Some(idx);
            *buf = history[idx].chars().collect();
        }
        Some(0) => return,
        Some(i) => {
            let idx = *i - 1;
            *hist_idx = Some(idx);
            *buf = history[idx].chars().collect();
        }
    }
    *cursor = buf.len();
}

fn history_next(
    history: &[String],
    buf: &mut Vec<char>,
    cursor: &mut usize,
    hist_idx: &mut Option<usize>,
    saved: &mut Vec<char>,
) {
    match hist_idx {
        None => return,
        Some(i) if *i + 1 >= history.len() => {
            *buf = saved.clone();
            *hist_idx = None;
        }
        Some(i) => {
            let idx = *i + 1;
            *hist_idx = Some(idx);
            *buf = history[idx].chars().collect();
        }
    }
    *cursor = buf.len();
}

fn char_width(c: char) -> usize {
    if c == '\t' {
        4
    } else {
        UnicodeWidthChar::width(c).unwrap_or(0)
    }
}

fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

fn draw(
    out: &mut impl Write,
    prompt: &str,
    buf: &[char],
    cursor: usize,
    prev_lines: &mut usize,
    prev_cursor_line: &mut usize,
) -> Result<()> {
    let text: String = buf.iter().collect();
    if !text.contains('\n') && *prev_lines == 1 {
        let prompt_w = str_width(prompt);
        let cursor_w: usize = buf[..cursor].iter().map(|&c| char_width(c)).sum();
        write!(out, "\r\x1b[K{}{}\r\x1b[{}C", prompt, text, prompt_w + cursor_w)?;
        *prev_cursor_line = 0;
        *prev_lines = 1;
        return Ok(());
    }
    // Multi-line rendering.
    if *prev_cursor_line > 0 {
        write!(out, "\x1b[{}A", *prev_cursor_line)?;
    }
    write!(out, "\r\x1b[J")?;
    let rendered = text.replace('\n', "\r\n");
    write!(out, "{}{}", prompt, rendered)?;
    let lines: Vec<&str> = text.split('\n').collect();
    let total_lines = lines.len();
    // Locate cursor line/column (prompt applies only to first line).
    let mut remaining = cursor;
    let mut cur_line = 0usize;
    let mut cur_col = str_width(prompt);
    for (i, line) in lines.iter().enumerate() {
        let lc = line.chars().count();
        if remaining <= lc {
            cur_line = i;
            cur_col = (if i == 0 { str_width(prompt) } else { 0 })
                + line.chars().take(remaining).map(char_width).sum::<usize>();
            break;
        } else {
            remaining -= lc + 1;
            cur_line = i;
        }
    }
    let up = (total_lines - 1).saturating_sub(cur_line);
    if up > 0 {
        write!(out, "\x1b[{}A", up)?;
    }
    write!(out, "\r\x1b[{}C", cur_col)?;
    *prev_lines = total_lines;
    *prev_cursor_line = cur_line;
    Ok(())
}
