use anyhow::Result;
use crossterm::event::{self, Event, KeyCode, KeyEventKind, KeyModifiers};
use crossterm::terminal;
use std::fs;
use std::io::{self, Write};
use std::path::PathBuf;
use unicode_width::UnicodeWidthChar;

const MAX_HISTORY: usize = 100;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ReadOutcome {
    Line(String),
    Interrupted,
    Eof,
}

pub struct Editor {
    history: Vec<String>,
    history_path: Option<PathBuf>,
}

fn home_dir() -> Option<PathBuf> {
    if let Some(h) = std::env::var_os("HOME") {
        if !h.is_empty() {
            return Some(PathBuf::from(h));
        }
    }
    #[cfg(unix)]
    unsafe {
        let uid = libc::getuid();
        let pw = libc::getpwuid(uid);
        if !pw.is_null() && !(*pw).pw_dir.is_null() {
            let cstr = std::ffi::CStr::from_ptr((*pw).pw_dir);
            return Some(PathBuf::from(cstr.to_string_lossy().into_owned()));
        }
    }
    None
}

fn unescape_v2(line: &str) -> String {
    let mut out = String::new();
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.peek().copied() {
                Some('n') => {
                    chars.next();
                    out.push('\n');
                }
                Some('\\') => {
                    chars.next();
                    out.push('\\');
                }
                _ => out.push('\\'),
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn escape_v2(entry: &str) -> String {
    let mut out = String::new();
    for c in entry.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            _ => out.push(c),
        }
    }
    out
}

impl Editor {
    pub fn new() -> Self {
        let history_path = home_dir().map(|h| h.join(".run_history"));
        let mut ed = Editor { history: Vec::new(), history_path };
        ed.load();
        ed
    }

    fn load(&mut self) {
        let Some(path) = &self.history_path else { return };
        let Ok(data) = fs::read_to_string(path) else { return };
        let mut lines = data.lines();
        let first = lines.next();
        let entries: Vec<String> = if first == Some("#V2") {
            lines.map(unescape_v2).collect()
        } else {
            let mut v = Vec::new();
            if let Some(f) = first {
                v.push(f.to_string());
            }
            v.extend(lines.map(|s| s.to_string()));
            v
        };
        for e in entries {
            self.push_history(e);
        }
    }

    fn push_history(&mut self, entry: String) {
        if entry.trim().is_empty() {
            return;
        }
        if self.history.last().is_some_and(|last| last == &entry) {
            return;
        }
        self.history.push(entry);
        if self.history.len() > MAX_HISTORY {
            let excess = self.history.len() - MAX_HISTORY;
            self.history.drain(0..excess);
        }
    }

    pub fn add_history(&mut self, entry: &str) {
        let e = entry.trim_end().to_string();
        self.push_history(e);
    }

    pub fn save_history(&self) {
        let Some(path) = &self.history_path else { return };
        let mut content = String::from("#V2\n");
        for e in &self.history {
            content.push_str(&escape_v2(e));
            content.push('\n');
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt;
            let mut opts = fs::OpenOptions::new();
            opts.write(true).create(true).truncate(true).mode(0o600);
            if let Ok(mut f) = opts.open(path) {
                let _ = f.write_all(content.as_bytes());
                return;
            }
        }
        let _ = fs::write(path, content);
    }

