fn is_word_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

fn word_start_before(buf: &[char], mut cursor: usize) -> usize {
    while cursor > 0 && buf[cursor - 1].is_whitespace() {
        cursor -= 1;
    }
    if cursor > 0 && is_word_char(buf[cursor - 1]) {
        while cursor > 0 && is_word_char(buf[cursor - 1]) {
            cursor -= 1;
        }
    } else {
        while cursor > 0 && !buf[cursor - 1].is_whitespace() && !is_word_char(buf[cursor - 1]) {
            cursor -= 1;
        }
    }
    cursor
}

fn word_end_after(buf: &[char], mut cursor: usize) -> usize {
    while cursor < buf.len() && buf[cursor].is_whitespace() {
        cursor += 1;
    }
    if cursor < buf.len() && is_word_char(buf[cursor]) {
        while cursor < buf.len() && is_word_char(buf[cursor]) {
            cursor += 1;
        }
    } else {
        while cursor < buf.len() && !buf[cursor].is_whitespace() && !is_word_char(buf[cursor]) {
            cursor += 1;
        }
    }
    cursor
}

fn history_prev(
    history: &[String],
    buf: &mut Vec<char>,
    cursor: &mut usize,
    hist_idx: &mut Option<usize>,
    saved: &mut Vec<char>,
) {
    if history.is_empty() {
        return;
    }
    match hist_idx {
        None => {
            *saved = buf.clone();
            let idx = history.len() - 1;
            *hist_idx = Some(idx);
            *buf = history[idx].chars().collect();
        }
        Some(0) => return,
        Some(i) => {
            let idx = *i - 1;
            *hist_idx = Some(idx);
            *buf = history[idx].chars().collect();
        }
    }
    *cursor = buf.len();
}

fn history_next(
    history: &[String],
    buf: &mut Vec<char>,
    cursor: &mut usize,
    hist_idx: &mut Option<usize>,
    saved: &mut Vec<char>,
) {
    match hist_idx {
        None => return,
        Some(i) if *i + 1 >= history.len() => {
            *buf = saved.clone();
            *hist_idx = None;
        }
        Some(i) => {
            let idx = *i + 1;
            *hist_idx = Some(idx);
            *buf = history[idx].chars().collect();
        }
    }
    *cursor = buf.len();
}

fn char_width(c: char) -> usize {
    if c == '\t' {
        4
    } else {
        UnicodeWidthChar::width(c).unwrap_or(0)
    }
}

fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

fn draw(
    out: &mut impl Write,
    prompt: &str,
    buf: &[char],
    cursor: usize,
    prev_lines: &mut usize,
    prev_cursor_line: &mut usize,
) -> Result<()> {
    let text: String = buf.iter().collect();
    if !text.contains('\n') && *prev_lines == 1 {
        let prompt_w = str_width(prompt);
        let cursor_w: usize = buf[..cursor].iter().map(|&c| char_width(c)).sum();
        write!(out, "\r\x1b[K{}{}\r\x1b[{}C", prompt, text, prompt_w + cursor_w)?;
        *prev_cursor_line = 0;
        *prev_lines = 1;
        return Ok(());
    }
    // Multi-line rendering.
    if *prev_cursor_line > 0 {
        write!(out, "\x1b[{}A", *prev_cursor_line)?;
    }
    write!(out, "\r\x1b[J")?;
    let rendered = text.replace('\n', "\r\n");
    write!(out, "{}{}", prompt, rendered)?;
    let lines: Vec<&str> = text.split('\n').collect();
    let total_lines = lines.len();
    // Locate cursor line/column (prompt applies only to first line).
    let mut remaining = cursor;
    let mut cur_line = 0usize;
    let mut cur_col = str_width(prompt);
    for (i, line) in lines.iter().enumerate() {
        let lc = line.chars().count();
        if remaining <= lc {
            cur_line = i;
            cur_col = (if i == 0 { str_width(prompt) } else { 0 })
                + line.chars().take(remaining).map(char_width).sum::<usize>();
            break;
        } else {
            remaining -= lc + 1;
            cur_line = i;
        }
    }
    let up = (total_lines - 1).saturating_sub(cur_line);
    if up > 0 {
        write!(out, "\x1b[{}A", up)?;
    }
    write!(out, "\r\x1b[{}C", cur_col)?;
    *prev_lines = total_lines;
    *prev_cursor_line = cur_line;
    Ok(())
}
