use anyhow::{anyhow, Context, Result};
use std::collections::HashMap;
use std::io::{BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdin, ChildStdout, Command, ExitStatus, Stdio};
use std::time::Instant;

use crate::detect;
use crate::editor::{Editor, ReadOutcome};
use crate::language::Language;
use crate::runner::{
    self, Ctx, Mode, Tools,
};

const HELP_TEXT: &str = "Commands:\n  :help                 Show this help message\n  :languages            List available languages\n  :lang <id>            Switch to language <id>\n  :detect on|off        Enable or disable auto language detection\n  :reset                Reset the current language session\n  :load <path>          Execute a file in the current language\n  :exit, :quit          Leave the REPL\nAny language id or alias works as a shortcut, e.g. :py, :cpp, :csharp, :php.";

struct Outcome {
    status: Option<ExitStatus>,
}

trait Session {
    fn execute(&mut self, code: &str) -> Result<Outcome>;
}

// ===================== utility =====================
fn first_word(s: &str) -> &str {
    s.split(|c: char| c.is_whitespace() || c == '(').next().unwrap_or("")
}
fn starts_word(s: &str, w: &str) -> bool {
    if s == w {
        return true;
    }
    if let Some(rest) = s.strip_prefix(w) {
        rest.chars().next().is_some_and(|c| c.is_whitespace() || c == '(' || c == '{' || c == ':' )
    } else {
        false
    }
}
fn starts_any(s: &str, words: &[&str]) -> bool {
    words.iter().any(|w| starts_word(s, w))
}
fn strip_semi(s: &str) -> &str {
    s.trim_end().trim_end_matches(';').trim_end()
}
fn contains_assignment(s: &str) -> bool {
    let bytes = s.as_bytes();
    for i in 0..bytes.len() {
        if bytes[i] == b'=' {
            let prev = if i > 0 { Some(bytes[i - 1]) } else { None };
            let next = bytes.get(i + 1).copied();
            if next == Some(b'=') || next == Some(b'>') {
                continue;
            }
            if matches!(prev, Some(b'=') | Some(b'!') | Some(b'<') | Some(b'>') | Some(b':')) {
                continue;
            }
            return true;
        }
    }
    false
}
fn indent_all(code: &str, indent: &str) -> String {
    code.lines()
        .map(|l| format!("{}{}", indent, l))
        .collect::<Vec<_>>()
        .join("\n")
}

#[derive(Clone)]
enum Entry {
    Imports(Vec<String>),
    Decl(String),
    Body(String),
}

// ===================== File session =====================
struct FileSession {
    lang: Language,
    ctx: Ctx,
    _temp: tempfile::TempDir,
    session_path: PathBuf,
    imports: Vec<String>,
    decls: Vec<String>,
    body: Vec<String>,
    total_entries: usize,
    last_stdout: String,
    last_stderr: String,
    checked_tools: Option<Tools>,
}

fn temp_for_session(lang: Language) -> Result<tempfile::TempDir> {
    let prefixed = matches!(
        lang,
        Language::Python
            | Language::Bash
            | Language::Cpp
            | Language::CSharp
            | Language::Dart
            | Language::Elixir
            | Language::Groovy
            | Language::Haskell
            | Language::Julia
            | Language::Kotlin
            | Language::Perl
            | Language::R
            | Language::Swift
    );
    if prefixed {
        let prefix = format!("run-{}-repl", lang.id());
        tempfile::Builder::new()
            .prefix(&prefix)
            .tempdir()
            .with_context(|| format!("failed to create temporary directory for {} repl", lang.id()))
    } else {
        let name = match lang {
            Language::C => "C",
            Language::Go => "Go",
            Language::Rust => "Rust",
            Language::Crystal => "Crystal",
            Language::Nim => "Nim",
            Language::Php => "PHP",
            Language::TypeScript => "TypeScript",
            Language::Zig => "Zig",
            Language::Lua => "Lua",
            _ => lang.id(),
        };
        tempfile::tempdir().with_context(|| format!("failed to create {} session workspace", name))
    }
}

fn session_filename(lang: Language) -> &'static str {
    match lang {
        Language::Python => "session.py",
        Language::Bash => "session.sh",
        Language::Go => "main.go",
        Language::Rust => "session.rs",
        Language::C => "main.c",
        Language::Cpp => "main.cpp",
        Language::Crystal => "session.cr",
        Language::CSharp => "Program.cs",
        Language::Dart => "session.dart",
        Language::Elixir => "session.exs",
        Language::Groovy => "session.groovy",
        Language::Haskell => "session.hs",
        Language::Julia => "session.jl",
        Language::Kotlin => "Session.kt",
        Language::Lua => "session.lua",
        Language::Nim => "session.nim",
        Language::Perl => "session.pl",
        Language::Php => "session.php",
        Language::R => "session.R",
        Language::Swift => "session.swift",
        Language::TypeScript => "session.ts",
        Language::Zig => "session.zig",
        _ => "session.txt",
    }
}

impl FileSession {
    fn new(ctx: &Ctx, lang: Language) -> Result<Self> {
        let mut checked_tools = None;
        match lang {
            Language::C | Language::Go | Language::Rust => {
                checked_tools = Some(runner::resolve_tools_no_probe(ctx, lang, Mode::Inline)?);
            }
            Language::TypeScript => {
                // Deno version check (custom message, stdin inherited).
                let Some(deno) = crate::language::which_first(&["deno"]) else {
                    return Err(anyhow!("failed to invoke Deno to check its version because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH."));
                };
                let _ = Command::new(&deno).arg("--version").stdin(Stdio::inherit()).output();
                checked_tools = Some(Tools { primary: deno, secondary: None });
            }
            _ => {}
        }
        let temp = temp_for_session(lang)?;
        let session_path = temp.path().join(session_filename(lang));
        let imports = match lang {
            Language::Go => vec!["\"fmt\"".to_string()],
            Language::C => vec!["#include <inttypes.h>".into(), "#include <stdio.h>".into()],
            Language::Haskell => vec!["import Prelude".into()],
            Language::Dart => vec!["import 'dart:async';".into()],
            Language::Swift => vec!["import Foundation".into()],
            _ => Vec::new(),
        };
        Ok(FileSession {
            lang,
            ctx: ctx.clone(),
            session_path,
            _temp: temp,
            imports,
            decls: Vec::new(),
            body: Vec::new(),
            total_entries: 0,
            last_stdout: String::new(),
            last_stderr: String::new(),
            checked_tools,
        })
    }

    fn tools(&self) -> Result<Tools> {
        if let Some(t) = &self.checked_tools {
            return Ok(t.clone());
        }
        runner::resolve_tools_no_probe(&self.ctx, self.lang, Mode::Inline)
    }

    fn build_file(&self, imports: &[String], decls: &[String], body: &[String]) -> String {
        build_session_file(self.lang, imports, decls, body)
    }

    fn run_once(&self, tools: &Tools) -> Result<(ExitStatus, String, String)> {
        let bin = &tools.primary;
        let path = &self.session_path;
        let temp = path.parent().unwrap_or(Path::new("."));
        // Helper closures
        let capture = |cmd: &mut Command| -> Result<(ExitStatus, String, String)> {
            let out = cmd.output().map_err(|e| {
                if self.lang == Language::Python {
                    anyhow::Error::from(e).context(format!(
                        "failed to run python session script {} with python3",
                        path.display()
                    ))
                } else {
                    anyhow::Error::from(e)
                }
            })?;
            Ok((
                out.status,
                String::from_utf8_lossy(&out.stdout).into_owned(),
                String::from_utf8_lossy(&out.stderr).into_owned(),
            ))
        };
        match self.lang {
            Language::Python | Language::Bash => {
                capture(Command::new(bin).arg(path).current_dir(temp))
            }
            Language::Go => capture(Command::new(bin).arg("run").arg("main.go").current_dir(temp)),
            Language::Dart => capture(Command::new(bin).args(["run", "--enable-asserts", "session.dart"]).current_dir(temp)),
            Language::Crystal => capture(Command::new(bin).args(["run", "session.cr", "--no-color"]).current_dir(temp)),
            Language::Elixir => capture(Command::new(bin).args(["--no-color", "session.exs"]).current_dir(temp)),
            Language::Groovy => capture(Command::new(bin).arg(path).current_dir(temp)),
            Language::Haskell => capture(Command::new(bin).arg("session.hs").current_dir(temp)),
            Language::Julia => capture(Command::new(bin).args(["--color=no", "--quiet", "session.jl"]).current_dir(temp)),
            Language::Lua => capture(Command::new(bin).arg("session.lua").current_dir(temp)),
            Language::Nim => capture(Command::new(bin).args(["r", "session.nim", "--colors:off", "--hints:off", "--verbosity:0"]).current_dir(temp)),
            Language::Perl => capture(Command::new(bin).arg("session.pl").current_dir(temp)),
            Language::Php => capture(Command::new(bin).arg("session.php").current_dir(temp)),
            Language::R => capture(Command::new(bin).arg("--vanilla").arg(path).current_dir(temp)),
            Language::Swift => capture(Command::new(bin).arg("session.swift").current_dir(temp)),
            Language::TypeScript => capture(Command::new(bin).args(["run", "--quiet", "--no-check", "--ext", "ts"]).arg(path)),
            Language::Zig => capture(Command::new(bin).arg("run").arg("session.zig").current_dir(temp)),
            Language::CSharp => {
                let proj = temp.join("Run.csproj");
                capture(Command::new(bin).args(["run", "--project"]).arg(&proj).arg("--nologo").current_dir(temp))
            }
            Language::C | Language::Cpp => {
                let (bin_name, flags): (&str, &[&str]) = if self.lang == Language::C {
                    ("run_c_binary", &["-std=c11", "-O0", "-Wall", "-Wextra"][..])
                } else {
                    ("run_cpp_binary", &["-std=c++17", "-O0", "-Wall", "-Wextra"][..])
                };
                let out_bin = temp.join(bin_name);
                let (st, so, se) = capture(Command::new(bin).arg(path).args(flags).arg("-o").arg(&out_bin))?;
                if !st.success() {
                    return Ok((st, so, se));
                }
                capture(Command::new(&out_bin).current_dir(temp))
            }
            Language::Rust => {
                let out_bin = temp.join("run_rust_binary");
                let (st, so, se) = capture(
                    Command::new(bin)
                        .args(["--color=never", "--edition=2021", "--crate-name", "run_snippet"])
                        .arg(path)
                        .arg("-o")
                        .arg(&out_bin),
                )?;
                if !st.success() {
                    return Ok((st, so, se));
                }
                capture(Command::new(&out_bin).current_dir(temp))
            }
            Language::Kotlin => {
                let jar = temp.join("session.jar");
                let (st, so, se) = capture(Command::new(bin).arg(path).args(["-include-runtime", "-d"]).arg(&jar))?;
                if !st.success() {
                    return Ok((st, so, se));
                }
                let java = crate::language::which_first(&["java"]).ok_or_else(|| {
                    anyhow!("Kotlin execution requires a `java` runtime. Install a JDK and ensure `java` is on your PATH.")
                })?;
                // Final stage inherits stdin (observed) but captures out/err.
                let out = Command::new(java)
                    .arg("-jar")
                    .arg(&jar)
                    .stdin(Stdio::inherit())
                    .output()?;
                Ok((
                    out.status,
                    String::from_utf8_lossy(&out.stdout).into_owned(),
                    String::from_utf8_lossy(&out.stderr).into_owned(),
                ))
            }
            _ => capture(Command::new(bin).arg(path).current_dir(temp)),
        }
    }
}

impl Session for FileSession {
    fn execute(&mut self, code: &str) -> Result<Outcome> {
        let tools = self.tools()?;
        let entry = classify(self.lang, code, self.body.len(), self.total_entries);
        let mut imports = self.imports.clone();
        let mut decls = self.decls.clone();
        let mut body = self.body.clone();
        match &entry {
            Entry::Imports(list) => {
                for item in list {
                    if !imports.contains(item) {
                        imports.push(item.clone());
                    }
                }
            }
            Entry::Decl(chunk) => decls.push(chunk.clone()),
            Entry::Body(chunk) => body.push(chunk.clone()),
        }
        // C# project file is (re)written alongside the session source.
        if self.lang == Language::CSharp {
            let proj = self.session_path.parent().unwrap().join("Run.csproj");
            std::fs::write(&proj, csharp_project(&self.ctx))?;
        }
        let content = self.build_file(&imports, &decls, &body);
        std::fs::write(&self.session_path, content)?;
        let (status, stdout, stderr) = self.run_once(&tools)?;
        print_diff(&self.last_stdout, &stdout, false);
        print_diff(&self.last_stderr, &stderr, true);
        if status.success() {
            self.imports = imports;
            self.decls = decls;
            self.body = body;
            self.total_entries += 1;
            self.last_stdout = stdout;
            self.last_stderr = stderr;
        }
        Ok(Outcome { status: Some(status) })
    }
}

fn csharp_project(ctx: &Ctx) -> String {
    let fw = ctx.dotnet_framework.as_deref().unwrap_or("net8.0");
    format!(
        "<Project Sdk=\"Microsoft.NET.Sdk\">\n  <PropertyGroup>\n    <OutputType>Exe</OutputType>\n    <TargetFramework>{}</TargetFramework>\n    <ImplicitUsings>enable</ImplicitUsings>\n    <Nullable>disable</Nullable>\n        <NoWarn>CS0219;CS8321</NoWarn>\n  </PropertyGroup>\n</Project>\n",
        fw
    )
}

fn print_diff(prev: &str, new: &str, is_stderr: bool) {
    let diff: &str = if let Some(rest) = new.strip_prefix(prev) {
        rest
    } else {
        new
    };
    if diff.is_empty() {
        return;
    }
    if is_stderr {
        let _ = write!(std::io::stderr(), "{}", diff);
        if !diff.ends_with('\n') {
            let _ = writeln!(std::io::stderr());
        }
        let _ = std::io::stderr().flush();
    } else {
        let _ = write!(std::io::stdout(), "{}", diff);
        if !diff.ends_with('\n') {
            let _ = writeln!(std::io::stdout());
        }
        let _ = std::io::stdout().flush();
    }
}

fn print_full(text: &str, is_stderr: bool) {
    if text.is_empty() {
        return;
    }
    if is_stderr {
        let _ = write!(std::io::stderr(), "{}", text);
        if !text.ends_with('\n') {
            let _ = writeln!(std::io::stderr());
        }
        let _ = std::io::stderr().flush();
    } else {
        let _ = write!(std::io::stdout(), "{}", text);
        if !text.ends_with('\n') {
            let _ = writeln!(std::io::stdout());
        }
        let _ = std::io::stdout().flush();
    }
}

// ===================== session file building =====================
const GO_HELPER: &str = "func __print(value interface{}) {\n\tif s, ok := value.(string); ok {\n\t\tfmt.Println(s)\n\t\treturn\n\t}\n\tfmt.Printf(\"%#v\\n\", value)\n}";
const RUST_HELPER: &str = "#![allow(unused_variables, unused_assignments, unused_mut, dead_code, unused_imports)]\nuse std::fmt::Debug;\n\nfn __print<T: Debug>(value: T) {\n    println!(\"{:?}\", value);\n}";
const C_HELPER: &str = "static void __print_int(long long value) { printf(\"%lld\\n\", value); }\nstatic void __print_uint(unsigned long long value) { printf(\"%llu\\n\", value); }\nstatic void __print_double(double value) { printf(\"%0.17g\\n\", value); }\nstatic void __print_cstr(const char *value) { if (!value) { printf(\"(null)\\n\"); } else { printf(\"%s\\n\", value); } }\nstatic void __print_char(int value) { printf(\"%d\\n\", value); }\nstatic void __print_pointer(const void *value) { printf(\"%p\\n\", value); }\n#define __print(value) _Generic((value), \\\n    char: __print_char, \\\n    signed char: __print_int, \\\n    short: __print_int, \\\n    int: __print_int, \\\n    long: __print_int, \\\n    long long: __print_int, \\\n    unsigned char: __print_uint, \\\n    unsigned short: __print_uint, \\\n    unsigned int: __print_uint, \\\n    unsigned long: __print_uint, \\\n    unsigned long long: __print_uint, \\\n    float: __print_double, \\\n    double: __print_double, \\\n    long double: __print_double, \\\n    char *: __print_cstr, \\\n    const char *: __print_cstr, \\\n    default: __print_pointer \\\n)(value)";
const CPP_HEADER: &str = "#include <iostream>\n#include <iomanip>\n#include <string>\n#include <vector>\n#include <map>\n#include <set>\n#include <unordered_map>\n#include <unordered_set>\n#include <deque>\n#include <list>\n#include <queue>\n#include <stack>\n#include <memory>\n#include <functional>\n#include <algorithm>\n#include <numeric>\n#include <cmath>\n\nusing namespace std;";
const CSHARP_HELPER: &str = "using System;\nusing System.Collections.Generic;\nusing System.Linq;\nusing System.Text;\nusing System.Threading.Tasks;\n#nullable disable\n\nstatic void __run_print(object value)\n{\n    if (value is null)\n    {\n        Console.WriteLine(\"null\");\n        return;\n    }\n\n    if (value is string s)\n    {\n        Console.WriteLine(s);\n        return;\n    }\n\n    // Pretty-print enumerables: [a, b, c]\n    if (value is System.Collections.IEnumerable enumerable && value is not string)\n    {\n        var sb = new StringBuilder();\n        sb.Append('[');\n        var first = true;\n        foreach (var item in enumerable)\n        {\n            if (!first) sb.Append(\", \");\n            first = false;\n            sb.Append(item is null ? \"null\" : item.ToString());\n        }\n        sb.Append(']');\n        Console.WriteLine(sb.ToString());\n        return;\n    }\n\n    Console.WriteLine(value);\n}";
const TS_HELPER: &str = "const __print = (value: unknown): void => {\n    if (typeof value === \"string\") {\n        console.log(value);\n        return;\n    }\n    try {\n        const serialized = JSON.stringify(value, null, 2);\n        if (serialized !== undefined) {\n            console.log(serialized);\n            return;\n        }\n    } catch (_) {\n        // ignore\n    }\n    console.log(String(value));\n};";

fn join_chunks(chunks: &[String]) -> String {
    let mut out = String::new();
    for c in chunks {
        out.push_str(c);
        if !c.ends_with('\n') {
            out.push('\n');
        }
    }
    out
}

fn build_session_file(lang: Language, imports: &[String], decls: &[String], body: &[String]) -> String {
    match lang {
        Language::Python => format!("import sys\nfrom math import *\n\n{}", join_chunks(body)),
        Language::Bash => format!("#!/usr/bin/env bash\nset -e\n{}", join_chunks(body)),
        Language::Go => {
            let mut s = String::from("package main\n\nimport (\n");
            for i in imports {
                s.push_str(&format!("\t{}\n", i));
            }
            s.push_str(")\n\n");
            s.push_str(GO_HELPER);
            s.push_str("\n\n");
            for d in decls {
                s.push_str(d);
                s.push_str("\n\n");
            }
            s.push_str("func main() {\n");
            s.push_str(&join_chunks(body));
            s.push_str("}\n");
            s
        }
        Language::Rust => {
            let mut s = String::from(RUST_HELPER);
            s.push_str("\n\n");
            for d in decls {
                s.push_str(d);
                s.push_str("\n\n");
            }
            s.push_str("fn main() {\n");
            s.push_str(&join_chunks(body));
            s.push_str("}\n");
            s
        }
        Language::C => {
            let mut s = String::new();
            for i in imports {
                s.push_str(i);
                s.push('\n');
            }
            s.push('\n');
            s.push_str(C_HELPER);
            s.push_str("\n\n");
            for d in decls {
                s.push_str(d);
                s.push_str("\n\n");
            }
            s.push_str("int main(void) {\n");
            s.push_str(&join_chunks(body));
            s.push_str("    return 0;\n}\n");
            s
        }
        Language::Cpp => {
            let mut s = String::from(CPP_HEADER);
            s.push_str("\n\n");
            for d in decls {
                s.push_str(d);
                s.push_str("\n\n");
            }
            s.push_str("int main()\n{\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    cout.setf(std::ios::boolalpha);\n");
            s.push_str(&join_chunks(body));
            s.push_str("    return 0;\n}\n");
            s
        }
        Language::Dart => {
            let mut s = String::new();
            for i in imports {
                s.push_str(i);
                s.push('\n');
            }
            s.push('\n');
            for d in decls {
                s.push_str(d);
                s.push_str("\n\n");
            }
            s.push_str("Future<void> main() async {\n");
            s.push_str(&join_chunks(body));
            s.push_str("}\n");
            s
        }
        Language::Kotlin => {
            let mut s = String::from("import kotlin.math.*\n\n");
            for d in decls {
                s.push_str(d);
                s.push_str("\n\n");
            }
            s.push_str("fun main() {\n");
            s.push_str(&join_chunks(body));
            s.push_str("}\n");
            s
        }
        Language::Haskell => {
            let mut s = String::new();
            for i in imports {
                s.push_str(i);
                s.push('\n');
            }
            s.push('\n');
            for d in decls {
                s.push_str(d);
                s.push_str("\n\n");
            }
            s.push_str("main :: IO ()\nmain = do\n");
            s.push_str(&join_chunks(body));
            s
        }
        Language::CSharp => format!("{}\n{}", CSHARP_HELPER, join_chunks(body)),
        Language::Groovy => format!("// Generated by run Groovy REPL\n{}", join_chunks(body)),
        Language::Julia => format!("\n{}", join_chunks(body)),
        Language::Perl => format!("use feature 'say';\nuse strict;\nuse warnings;\n\n{}", join_chunks(body)),
        Language::Php => format!("<?php\n{}", join_chunks(body)),
        Language::R => format!("options(warn=1)\n{}", join_chunks(body)),
        Language::Swift => {
            let mut s = String::new();
            for i in imports {
                s.push_str(i);
                s.push('\n');
            }
            s.push('\n');
            // Swift decls are stored in body as chunks with trailing blank handling in join.
            s.push_str(&join_chunks(body));
            s
        }
        Language::TypeScript => format!("{}\n\n{}", TS_HELPER, join_chunks(body)),
        Language::Zig => {
            let mut s = String::from("const std = @import(\"std\");\n\n");
            for d in decls {
                s.push_str(d);
                s.push_str("\n\n");
            }
            s.push_str("pub fn main() !void {\n");
            s.push_str(&join_chunks(body));
            s.push_str("}\n");
            s
        }
        _ => join_chunks(body),
    }
}

// ===================== classification / transforms =====================
fn classify(lang: Language, code: &str, body_idx: usize, total_idx: usize) -> Entry {
    let trimmed = code.trim();
    let first_line = trimmed.lines().next().unwrap_or("").trim();
    let single = !trimmed.contains('\n');
    match lang {
        Language::Python => {
            if single && is_python_expr(trimmed) {
                Entry::Body(format!(
                    "__run_value_{} = ({})\nprint(repr(__run_value_{}), flush=True)",
                    total_idx, trimmed, total_idx
                ))
            } else {
                Entry::Body(code.trim_end_matches('\n').to_string())
            }
        }
        Language::Bash => Entry::Body(code.trim_end_matches('\n').to_string()),
        Language::Go => classify_go(code, trimmed, first_line, single),
        Language::Rust => classify_rust(code, trimmed, first_line, single),
        Language::C => classify_c(code, trimmed, first_line, single),
        Language::Cpp => classify_cpp(code, trimmed, first_line, single),
        Language::Dart => classify_dart(code, trimmed, first_line, single),
        Language::Kotlin => classify_kotlin(code, trimmed, first_line, single, body_idx),
        Language::Haskell => classify_haskell(code, trimmed, first_line, single),
        Language::CSharp => classify_csharp(trimmed, single, total_idx),
        Language::Crystal => {
            let chunk = if single && starts_any(first_line, &["def", "class", "module", "require", "if", "unless", "while", "until", "begin", "case", "struct", "enum", "lib", "macro", "include", "extend"]) {
                trimmed.to_string()
            } else if single {
                format!("p({})", strip_semi(trimmed))
            } else {
                code.trim_end().to_string()
            };
            Entry::Body(format!("{}\n", chunk))
        }
        Language::Elixir => classify_elixir(trimmed, first_line, single),
        Language::Groovy => classify_groovy(trimmed, first_line, single, total_idx),
        Language::Julia => {
            if starts_any(first_line, &["function", "struct", "mutable", "abstract", "module", "macro"]) {
                Entry::Body(format!("{}\n", trimmed))
            } else if single && (starts_any(first_line, &["using", "import", "if", "for", "while", "try", "begin", "let", "return"]) || contains_assignment(trimmed)) {
                Entry::Body(trimmed.to_string())
            } else if single {
                Entry::Body(format!("println({});", strip_semi(trimmed)))
            } else {
                Entry::Body(code.trim_end().to_string())
            }
        }
        Language::Nim => classify_nim(trimmed, first_line, single),
        Language::Perl => {
            if starts_any(first_line, &["sub"]) {
                Entry::Body(format!("{}\n", trimmed))
            } else if single && is_perl_statement(trimmed) {
                Entry::Body(trimmed.to_string())
            } else if single {
                Entry::Body(format!("say({});", strip_semi(trimmed)))
            } else {
                Entry::Body(code.trim_end().to_string())
            }
        }
        Language::Php => Entry::Body(strip_semi(trimmed).to_string()),
        Language::R => {
            if single && (trimmed.contains("<-") || contains_assignment(trimmed) || starts_any(first_line, &["library", "require", "print", "if", "for", "while", "function"])) {
                Entry::Body(trimmed.to_string())
            } else if single {
                Entry::Body(format!("print(({}))", trimmed))
            } else {
                Entry::Body(code.trim_end().to_string())
            }
        }
        Language::Swift => classify_swift(code, trimmed, first_line, single),
        Language::TypeScript => classify_ts(trimmed, first_line, single),
        Language::Zig => classify_zig(code, trimmed, first_line, single),
        _ => Entry::Body(code.trim_end().to_string()),
    }
}

fn is_python_expr(t: &str) -> bool {
    if t.is_empty() || t.contains(';') {
        return false;
    }
    if t.starts_with("print(") {
        return false;
    }
    const KW: &[&str] = &[
        "import", "from", "def", "class", "for", "while", "if", "elif", "else", "try", "except",
        "finally", "with", "return", "del", "global", "nonlocal", "assert", "raise", "pass",
        "break", "continue", "async", "yield",
    ];
    if starts_any(t, KW) || t.starts_with('@') {
        return false;
    }
    // Augmented assignments
    for op in ["+=", "-=", "*=", "/=", "//=", "%=", "**=", "&=", "|=", "^=", ">>=", "<<="] {
        if t.contains(op) {
            return false;
        }
    }
    if contains_assignment(t) {
        return false;
    }
    true
}

fn body_indented(code: &str, indent: &str) -> String {
    indent_all(code.trim_end_matches('\n'), indent)
}

fn classify_go(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("import ") || first_line == "import (" || first_line.starts_with("import(") {
        // Extract quoted import specs (keep alias if present before quote on a line).
        let mut specs = Vec::new();
        for line in trimmed.lines() {
            let l = line.trim();
            if let Some(start) = l.find('"') {
                if let Some(end_rel) = l[start + 1..].find('"') {
                    let quoted = &l[start..=start + 1 + end_rel];
                    let before = l[..start].trim();
                    let alias = before.strip_prefix("import").map(|s| s.trim()).unwrap_or(before);
                    if alias.is_empty() || alias == "(" {
                        specs.push(quoted.to_string());
                    } else {
                        specs.push(format!("{} {}", alias, quoted));
                    }
                }
            }
        }
        if !specs.is_empty() {
            return Entry::Imports(specs);
        }
    }
    if starts_any(first_line, &["func", "var", "const", "type"]) {
        return Entry::Decl(trimmed.to_string());
    }
    let clean = strip_semi(trimmed);
    if single {
        if let Some(pos) = clean.find(":=") {
            let lhs = clean[..pos].trim();
            return Entry::Body(format!("\t{}\n\t_ = {}", clean, lhs));
        }
        let is_stmt = starts_any(clean, &["if", "for", "switch", "select", "return", "go", "defer", "else"])
            || clean.starts_with("fmt.Print")
            || clean.starts_with("print(")
            || clean.starts_with("println(")
            || contains_assignment(clean)
            || clean.ends_with("++")
            || clean.ends_with("--");
        if is_stmt {
            Entry::Body(format!("\t{}", clean))
        } else {
            Entry::Body(format!("\t__print({});", clean))
        }
    } else {
        Entry::Body(body_indented(code, "\t"))
    }
}

fn classify_rust(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    let clean_all = strip_semi(trimmed);
    if starts_any(first_line, &["fn", "pub", "struct", "enum", "trait", "impl", "type", "mod", "use", "const", "static"]) {
        return Entry::Decl(clean_all.to_string());
    }
    if single {
        let is_stmt = starts_any(clean_all, &["let", "return", "if", "for", "while", "loop", "match", "break", "continue"]);
        if is_stmt {
            Entry::Body(format!("    {}", clean_all))
        } else {
            Entry::Body(format!("    __print({});", clean_all))
        }
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn is_c_function_def(t: &str) -> bool {
    if starts_any(t, &["if", "for", "while", "switch", "return", "sizeof"]) {
        return false;
    }
    // e.g. `void foo() { ... }` / `int bar(int x) { ... }`
    let Some(lp) = t.find('(') else { return false };
    if !t.contains('{') {
        return false;
    }
    let before = &t[..lp];
    // need at least two tokens (return type + name)
    before.split_whitespace().count() >= 2
}

fn classify_c(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("#include") && single {
        return Entry::Imports(vec![trimmed.to_string()]);
    }
    if starts_any(first_line, &["struct", "union", "enum", "typedef"]) || is_c_function_def(trimmed) {
        return Entry::Decl(strip_semi(trimmed).to_string());
    }
    let clean = strip_semi(trimmed);
    if single {
        const TYPES: &[&str] = &[
            "int", "char", "long", "short", "unsigned", "signed", "float", "double", "size_t",
            "bool", "_Bool", "void", "const", "static", "extern", "volatile", "register", "auto",
        ];
        let is_decl = starts_any(clean, TYPES);
        let is_inc = clean.ends_with("++") || clean.ends_with("--") || clean.starts_with("++") || clean.starts_with("--");
        let is_aug = ["+=", "-=", "*=", "/=", "%=", "&=", "|=", "^="].iter().any(|op| clean.contains(op));
        if is_decl || is_inc || is_aug {
            Entry::Body(format!("    {}", clean))
        } else {
            Entry::Body(format!("    __print({});", clean))
        }
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn classify_cpp(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if starts_any(first_line, &["struct", "class", "enum", "union", "template", "namespace", "typedef"]) || is_c_function_def(trimmed) {
        return Entry::Decl(strip_semi(trimmed).to_string());
    }
    let clean = strip_semi(trimmed);
    if single {
        const TYPES: &[&str] = &[
            "int", "char", "long", "short", "unsigned", "signed", "float", "double", "size_t",
            "bool", "void", "const", "static", "auto", "std::string", "string", "std::vector", "vector",
        ];
        let is_stmt = starts_any(clean, TYPES)
            || starts_any(clean, &["if", "for", "while", "switch", "return", "do", "else", "using", "#include", "cout", "cerr", "cin"])
            || clean.starts_with("#")
            || contains_assignment(clean)
            || clean.ends_with("++")
            || clean.ends_with("--")
            || ["+=", "-=", "*=", "/="].iter().any(|op| clean.contains(op));
        if is_stmt {
            Entry::Body(format!("    {}", clean))
        } else {
            Entry::Body(format!("    std::cout << ({}) << std::endl;", clean))
        }
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn classify_dart(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("import ") {
        return Entry::Imports(vec![first_line.to_string()]);
    }
    if starts_any(first_line, &["class", "enum", "mixin", "extension", "typedef"])
        || is_dart_function(first_line)
    {
        return Entry::Decl(trimmed.to_string());
    }
    if single {
        let is_stmt = starts_any(trimmed, &["var", "final", "const", "late", "if", "for", "while", "switch", "return", "try"])
            || trimmed.ends_with("++")
            || trimmed.ends_with("--");
        if is_stmt {
            Entry::Body(format!("  {}", trimmed))
        } else {
            Entry::Body(format!("  print(({}));", strip_semi(trimmed)))
        }
    } else {
        Entry::Body(body_indented(code, "  "))
    }
}

fn is_dart_function(line: &str) -> bool {
    // `void foo() {}` / `int foo() {}` style (leading simple type then name + parens)
    let Some(lp) = line.find('(') else { return false };
    if !line.contains('{') {
        return false;
    }
    let before = &line[..lp];
    let toks: Vec<&str> = before.split_whitespace().collect();
    if toks.len() < 2 {
        return false;
    }
    matches!(toks[0], "void" | "int" | "double" | "num" | "bool" | "String" | "dynamic" | "Object")
}

fn classify_kotlin(code: &str, trimmed: &str, first_line: &str, single: bool, body_idx: usize) -> Entry {
    if starts_any(first_line, &["import", "package", "val", "var", "class", "data", "sealed", "interface", "object", "enum", "fun", "suspend", "annotation", "typealias"]) {
        return Entry::Decl(trimmed.to_string());
    }
    if single {
        let is_stmt = starts_any(trimmed, &["println", "print", "for", "while", "return", "when", "throw"])
            || contains_assignment(trimmed);
        if is_stmt {
            Entry::Body(format!("    {}", trimmed))
        } else {
            Entry::Body(format!(
                "    val __repl_val_{} = ({})\n    println(__repl_val_{})",
                body_idx, strip_semi(trimmed), body_idx
            ))
        }
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn classify_haskell(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("import ") {
        return Entry::Imports(vec![first_line.to_string()]);
    }
    if starts_any(first_line, &["data", "newtype", "type", "class", "instance"]) {
        return Entry::Decl(trimmed.to_string());
    }
    if single && is_haskell_binding(trimmed) {
        return Entry::Decl(trimmed.to_string());
    }
    if single && starts_word(trimmed, "let") {
        return Entry::Body(format!("    {}\n    return ()", trimmed));
    }
    if single && starts_word(trimmed, "if") {
        return Entry::Body(format!("    {}", trimmed));
    }
    if single {
        Entry::Body(format!("    print (({}))", trimmed))
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn is_haskell_binding(t: &str) -> bool {
    // name (args)* = ...   with a single '=' (not ==)
    let Some(pos) = t.find('=') else { return false };
    if t[pos..].starts_with("==") {
        return false;
    }
    let lhs = t[..pos].trim();
    if lhs.is_empty() {
        return false;
    }
    let first = lhs.split_whitespace().next().unwrap_or("");
    first.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
        && !matches!(first, "let" | "if" | "case")
        && !lhs.contains("<-")
}

fn classify_csharp(trimmed: &str, single: bool, total_idx: usize) -> Entry {
    if !single {
        return Entry::Body(trimmed.to_string());
    }
    if starts_word(trimmed, "using") || starts_word(trimmed, "return") {
        return Entry::Body(strip_semi(trimmed).to_string());
    }
    let is_stmt = starts_any(
        trimmed,
        &[
            "class", "interface", "struct", "enum", "namespace", "record", "if", "for", "foreach",
            "while", "switch", "try", "Console.WriteLine", "Console.Write", "void", "public",
            "private", "protected", "static", "async",
        ],
    ) || is_csharp_decl(trimmed)
        || contains_assignment(trimmed);
    if is_stmt {
        Entry::Body(trimmed.to_string())
    } else {
        Entry::Body(format!(
            "var __repl_val_{} = ({});\n__run_print(__repl_val_{});",
            total_idx,
            strip_semi(trimmed),
            total_idx
        ))
    }
}

fn is_csharp_decl(t: &str) -> bool {
    // var/int/string/... name = ...  or Type name;
    let mut it = t.split_whitespace();
    let Some(first) = it.next() else { return false };
    if first == "var" {
        return t.contains('=');
    }
    const TYPES: &[&str] = &["int", "string", "double", "float", "bool", "long", "short", "byte", "char", "decimal", "object", "dynamic", "uint", "ulong"];
    if TYPES.contains(&first) {
        return it.next().is_some();
    }
    false
}

fn classify_elixir(trimmed: &str, first_line: &str, single: bool) -> Entry {
    if starts_any(first_line, &["defmodule", "defprotocol", "import", "alias", "use", "require"]) {
        return Entry::Body(format!("{}\n", trimmed));
    }
    if single {
        if let Some(pos) = trimmed.find(" = ") {
            let lhs = trimmed[..pos].trim();
            // simple variable binding
            if lhs.chars().next().is_some_and(|c| c.is_ascii_lowercase() || c == '_')
                && lhs.chars().all(|c| c.is_alphanumeric() || c == '_')
            {
                return Entry::Body(format!("{}\n_ = {}", trimmed, lhs));
            }
        }
        if starts_any(trimmed, &["def", "defp"]) {
            return Entry::Body(trimmed.to_string());
        }
        Entry::Body(format!("IO.inspect(({}))", trimmed))
    } else {
        Entry::Body(trimmed.to_string())
    }
}

fn classify_groovy(trimmed: &str, first_line: &str, single: bool, total_idx: usize) -> Entry {
    if starts_any(first_line, &["import", "class", "interface", "enum", "trait", "package"]) {
        return Entry::Body(trimmed.to_string());
    }
    if !single {
        return Entry::Body(trimmed.to_string());
    }
    // function definition: def name(...) ...
    if starts_word(trimmed, "def") {
        let rest = trimmed[3..].trim_start();
        if rest.contains('(') {
            return Entry::Body(trimmed.to_string());
        }
    }
    let starts_print = trimmed.starts_with("println") || trimmed.starts_with("print ") || trimmed.starts_with("print(");
    if starts_print || starts_any(trimmed, &["if", "for", "while", "switch", "try", "return"]) {
        return Entry::Body(trimmed.to_string());
    }
    Entry::Body(format!(
        "def __run_value_{} = ({});\nprintln(__run_value_{});",
        total_idx,
        strip_semi(trimmed),
        total_idx
    ))
}

fn classify_nim(trimmed: &str, first_line: &str, single: bool) -> Entry {
    if !single {
        return Entry::Body(format!("{}\n", trimmed));
    }
    if starts_any(first_line, &["var", "let", "const"]) {
        let after = first_line.split_whitespace().nth(1).unwrap_or("");
        let name: String = after.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
        return Entry::Body(format!("{}\ndiscard {}\n", trimmed, name));
    }
    if starts_any(
        first_line,
        &["import", "include", "from", "proc", "func", "method", "macro", "template", "iterator", "type", "if", "for", "while", "when", "try", "case"],
    ) {
        return Entry::Body(format!("{}\n", trimmed));
    }
    Entry::Body(format!("echo ({})\n", strip_semi(trimmed)))
}

fn is_perl_statement(t: &str) -> bool {
    starts_any(t, &["my", "our", "local", "state", "use", "no", "require", "sub", "if", "unless", "for", "foreach", "while", "until", "given", "return", "package"])
        || ((t.starts_with('$') || t.starts_with('@') || t.starts_with('%')) && contains_assignment(t))
}

fn classify_swift(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("import ") {
        return Entry::Imports(vec![first_line.to_string()]);
    }
    if starts_any(first_line, &["func", "struct", "class", "enum", "protocol", "extension", "typealias"]) {
        return Entry::Body(format!("{}\n", trimmed));
    }
    if single {
        let is_stmt = starts_any(trimmed, &["let", "var", "if", "for", "while", "switch", "guard", "return", "do"])
            || contains_assignment(trimmed);
        if is_stmt {
            Entry::Body(trimmed.to_string())
        } else {
            Entry::Body(format!("print(({}))", strip_semi(trimmed)))
        }
    } else {
        Entry::Body(code.trim_end().to_string())
    }
}

fn classify_ts(trimmed: &str, first_line: &str, single: bool) -> Entry {
    if !single {
        return Entry::Body(trimmed.to_string());
    }
    if starts_any(
        first_line,
        &["import", "export", "interface", "type", "function", "class", "abstract", "declare", "enum", "namespace", "const", "let", "var", "if", "for", "while", "switch", "try", "return"],
    ) {
        // Observed semicolon stripping on declarations/imports.
        return Entry::Body(strip_semi(trimmed).to_string());
