// ===================== Lua (stateless file) =====================
struct LuaSession {
    ctx: Ctx,
    _temp: tempfile::TempDir,
    path: PathBuf,
}
impl LuaSession {
    fn new(ctx: &Ctx) -> Result<Self> {
        let temp = temp_for_session(Language::Lua)?;
        let path = temp.path().join("session.lua");
        Ok(LuaSession { ctx: ctx.clone(), _temp: temp, path })
    }
}
impl Session for LuaSession {
    fn execute(&mut self, code: &str) -> Result<Outcome> {
        let tools = runner::resolve_tools_no_probe(&self.ctx, Language::Lua, Mode::Inline)?;
        let content = lua_transform(code);
        std::fs::write(&self.path, content)?;
        let out = Command::new(&tools.primary)
            .arg("session.lua")
            .current_dir(self.path.parent().unwrap())
            .output()?;
        print_full(&String::from_utf8_lossy(&out.stdout), false);
        print_full(&String::from_utf8_lossy(&out.stderr), true);
        Ok(Outcome { status: Some(out.status) })
    }
}

fn lua_transform(code: &str) -> String {
    let t = code.trim();
    let is_stmt = starts_any(t, &["local", "function", "if", "for", "while", "repeat", "do", "return", "break", "goto", "end", "else", "elseif"])
        || contains_assignment(t);
    if is_stmt || t.contains('\n') {
        return runner::ensure_nl(code);
    }
    format!(
        "do\n    local __run_pack = table.pack(({}))\n    local __run_n = __run_pack.n or #__run_pack\n    if __run_n > 0 then\n        for __run_i = 1, __run_n do\n            if __run_i > 1 then io.write(\"\\t\") end\n            local __run_val = __run_pack[__run_i]\n            if __run_val == nil then\n                io.write(\"nil\")\n            else\n                io.write(tostring(__run_val))\n            end\n        end\n        io.write(\"\\n\")\n    end\nend\n",
        t
    )
}

