// ===================== JavaScript persistent =====================
struct JsSession {
    child: Child,
    stdin: ChildStdin,
    reader: BufReader<ChildStdout>,
}
impl JsSession {
    fn new() -> Result<Self> {
        let bin = crate::language::resolve_first(&["node", "nodejs"]);
        let mut child = Command::new(&bin)
            .args(["--interactive", "--no-warnings", "--experimental-repl-await"])
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .with_context(|| "failed to start node REPL".to_string())?;
        let stdin = child.stdin.take().unwrap();
        let stdout = child.stdout.take().unwrap();
        if let Some(mut stderr) = child.stderr.take() {
            std::thread::spawn(move || {
                let mut buf = [0u8; 4096];
                loop {
                    match stderr.read(&mut buf) {
                        Ok(0) | Err(_) => break,
                        Ok(n) => {
                            let _ = std::io::stderr().write_all(&buf[..n]);
                            let _ = std::io::stderr().flush();
                        }
                    }
                }
            });
        }
        let mut sess = JsSession { child, stdin, reader: BufReader::new(stdout) };
        // Discard banner up to first prompt.
        let _ = sess.read_until_prompt();
        Ok(sess)
    }

    fn read_until_prompt(&mut self) -> Result<String> {
        let mut buf: Vec<u8> = Vec::new();
        self.reader.read_until(b'>', &mut buf)?;
        // Consume the single space that follows the prompt '>'.
        let mut one = [0u8; 1];
        let _ = self.reader.read_exact(&mut one);
        if buf.last() == Some(&b'>') {
            buf.pop();
        }
        Ok(String::from_utf8_lossy(&buf).into_owned())
    }
}
impl Session for JsSession {
    fn execute(&mut self, code: &str) -> Result<Outcome> {
        self.stdin.write_all(code.as_bytes())?;
        self.stdin.write_all(b"\n")?;
        self.stdin.flush()?;
        let out = self.read_until_prompt()?;
        print_full(&out, false);
        Ok(Outcome { status: None })
    }
}
impl Drop for JsSession {
    fn drop(&mut self) {
        let _ = self.stdin.write_all(b".exit\n");
        let _ = self.stdin.flush();
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

// ===================== REPL loop =====================
fn create_session(ctx: &Ctx, lang: Language) -> Result<Box<dyn Session>> {
    let sess: Box<dyn Session> = match lang {
        Language::JavaScript => Box::new(JsSession::new()?),
        Language::Ruby => Box::new(RubySession { ctx: ctx.clone() }),
        Language::Java => Box::new(JavaSession { ctx: ctx.clone() }),
        Language::Lua => Box::new(LuaSession::new(ctx)?),
        _ => Box::new(FileSession::new(ctx, lang)?),
    };
    Ok(sess)
}

fn get_session<'a>(
    sessions: &'a mut HashMap<Language, Box<dyn Session>>,
    ctx: &Ctx,
    lang: Language,
) -> Result<&'a mut Box<dyn Session>> {
    if !sessions.contains_key(&lang) {
        let sess = create_session(ctx, lang)
            .with_context(|| format!("failed to start {} session", lang.id()))?;
        sessions.insert(lang, sess);
    }
    Ok(sessions.get_mut(&lang).unwrap())
}

fn bracket_unbalanced(code: &str) -> bool {
    let mut par = 0i32;
    let mut brk = 0i32;
    let mut brc = 0i32;
    let mut in_single = false;
    let mut in_double = false;
    let mut in_back = false;
    let mut escaped = false;
    for c in code.chars() {
        if escaped {
            escaped = false;
            continue;
        }
        if c == '\\' && (in_single || in_double || in_back) {
            escaped = true;
            continue;
        }
        if in_single {
            if c == '\'' {
                in_single = false;
            }
            continue;
        }
        if in_double {
            if c == '"' {
                in_double = false;
            }
            continue;
        }
        if in_back {
            if c == '`' {
                in_back = false;
            }
            continue;
        }
        match c {
            '\'' => in_single = true,
            '"' => in_double = true,
            '`' => in_back = true,
            '(' => par += 1,
            ')' => par -= 1,
            '[' => brk += 1,
            ']' => brk -= 1,
            '{' => brc += 1,
            '}' => brc -= 1,
            _ => {}
        }
    }
    par > 0 || brk > 0 || brc > 0
}

fn needs_continuation(code: &str, lang: Language) -> bool {
    if bracket_unbalanced(code) {
        return true;
    }
    if lang == Language::Python {
        let first = code.lines().next().unwrap_or("").trim_end();
        if first.ends_with(':') {
            // A blank line after the header (within pasted input) terminates.
            let has_blank_after = code.lines().skip(1).any(|l| l.trim().is_empty());
            return !has_blank_after;
        }
        return false;
    }
    let last = code.lines().rev().find(|l| !l.trim().is_empty()).unwrap_or("").trim_end();
    if last.is_empty() {
        return false;
    }
    if last == "return" || last.ends_with(" return") {
        return true;
    }
    let last_char = last.chars().last().unwrap();
    matches!(
        last_char,
        '\\' | '+' | '-' | '*' | '/' | '%' | '=' | '<' | '>' | '&' | '|' | '^' | ',' | '.' | ':' | '?' | '!'
    )
}

fn print_exit_line(status: ExitStatus, started: Instant) {
    if !status.success() {
        println!(
            "[exit code {}] ({}ms)",
            status.code().unwrap_or(1),
            started.elapsed().as_millis()
        );
    }
}

pub fn run_repl(ctx: &Ctx, initial: Language, auto_detect_initial: bool) -> Result<()> {
    println!("run universal REPL. Type :help for commands.");
    let mut editor = Editor::new();
    let mut sessions: HashMap<Language, Box<dyn Session>> = HashMap::new();
    let mut current = initial;
    let mut auto_detect = auto_detect_initial;

    'outer: loop {
        let prompt = format!("{}>>> ", current.id());
        let first = match editor.readline(&prompt)? {
            ReadOutcome::Line(s) => s,
            ReadOutcome::Interrupted => continue,
            ReadOutcome::Eof => {
                println!("bye");
                break;
            }
        };
        let is_command = first.trim_start().starts_with(':');
        let mut code = first.clone();
        let mut cancelled = false;
        let mut eof = false;
        if !is_command {
            while needs_continuation(&code, current) {
                match editor.readline("... ")? {
                    ReadOutcome::Line(next) => {
                        if next.trim().is_empty()
                            && current == Language::Python
                            && !bracket_unbalanced(&code)
                        {
                            break;
                        }
                        code.push('\n');
                        code.push_str(&next);
                    }
                    ReadOutcome::Interrupted => {
                        cancelled = true;
                        break;
                    }
                    ReadOutcome::Eof => {
                        eof = true;
                        break;
                    }
                }
            }
        }
        if cancelled {
            continue;
        }
        if eof {
            println!("bye");
            break;
        }
        if code.trim().is_empty() {
            continue;
        }
        editor.add_history(&code);

        // Commands
        let trimmed = code.trim();
        if trimmed.starts_with(':') {
            let body = trimmed.trim_start_matches(':').trim_start();
            let mut parts = body.split_whitespace();
            let cmd = parts.next().unwrap_or("");
            if cmd.is_empty() {
                continue;
            }
            match cmd {
                "help" => {
                    println!("{}", HELP_TEXT);
                }
                "languages" => {
                    println!("available languages: {}", crate::language::AVAILABLE);
                }
                "lang" => {
                    let Some(arg) = parts.next() else {
                        println!("usage: :lang <language>");
                        continue;
                    };
                    let new_lang = Language::parse_repl(arg)?;
                    if new_lang == current {
                        println!("already using {}", current.id());
                    } else {
                        current = new_lang;
                        println!("switched to {}", current.id());
                    }
                }
                "detect" => {
                    match parts.next() {
                        None => {
                            if auto_detect {
                                println!("auto-detect is enabled");
                            } else {
                                println!("auto-detect is disabled");
                            }
                        }
                        Some("on") => {
                            auto_detect = true;
                            println!("auto-detect enabled");
                        }
                        Some("off") => {
                            auto_detect = false;
                            println!("auto-detect disabled");
                        }
                        Some("toggle") => {
                            auto_detect = !auto_detect;
                            if auto_detect {
                                println!("auto-detect enabled");
                            } else {
                                println!("auto-detect disabled");
                            }
                        }
                        Some(_) => {
                            println!("usage: :detect <on|off|toggle>");
                        }
                    }
                }
                "reset" => {
                    sessions.remove(&current);
                    println!("session for '{}' reset", current.id());
                }
                "load" => {
                    let Some(path) = parts.next() else {
                        println!("usage: :load <path>");
                        continue;
                    };
                    let tools = runner::resolve_tools_no_probe(ctx, current, Mode::File)?;
                    let started = Instant::now();
                    let st = runner::run_file_status(ctx, current, Path::new(path), &tools)?;
                    print_exit_line(st, started);
                }
                "exit" | "quit" => {
                    break 'outer;
                }
                _ => {
                    if let Some(new_lang) = Language::parse(cmd) {
                        if new_lang == current {
                            println!("already using {}", current.id());
                        } else {
                            current = new_lang;
                            println!("switched to {}", current.id());
                        }
                    } else {
                        println!("unknown command: :{}. Type :help for help.", cmd);
                    }
                }
            }
            continue;
        }

        // Code execution
        if auto_detect {
            let detected = detect::detect_language(&code);
            if detected != current {
                println!("[auto-detect] switching {} \u{2192} {}", current.id(), detected.id());
                current = detected;
            }
        }
        let started = Instant::now();
        let outcome = {
            let sess = get_session(&mut sessions, ctx, current)?;
            sess.execute(&code)?
        };
        if let Some(st) = outcome.status {
            print_exit_line(st, started);
        }
    }
    drop(sessions);
    editor.save_history();
    Ok(())
}
