fn classify(lang: Language, code: &str, body_idx: usize, total_idx: usize) -> Entry {
    let trimmed = code.trim();
    let first_line = trimmed.lines().next().unwrap_or("").trim();
    let single = !trimmed.contains('\n');
    match lang {
        Language::Python => {
            if single && is_python_expr(trimmed) {
                Entry::Body(format!(
                    "__run_value_{} = ({})\nprint(repr(__run_value_{}), flush=True)",
                    total_idx, trimmed, total_idx
                ))
            } else {
                Entry::Body(code.trim_end_matches('\n').to_string())
            }
        }
        Language::Bash => Entry::Body(code.trim_end_matches('\n').to_string()),
        Language::Go => classify_go(code, trimmed, first_line, single),
        Language::Rust => classify_rust(code, trimmed, first_line, single),
        Language::C => classify_c(code, trimmed, first_line, single),
        Language::Cpp => classify_cpp(code, trimmed, first_line, single),
        Language::Dart => classify_dart(code, trimmed, first_line, single),
        Language::Kotlin => classify_kotlin(code, trimmed, first_line, single, body_idx),
        Language::Haskell => classify_haskell(code, trimmed, first_line, single),
        Language::CSharp => classify_csharp(trimmed, single, total_idx),
        Language::Crystal => {
            let chunk = if single && starts_any(first_line, &["def", "class", "module", "require", "if", "unless", "while", "until", "begin", "case", "struct", "enum", "lib", "macro", "include", "extend"]) {
                trimmed.to_string()
            } else if single {
                format!("p({})", strip_semi(trimmed))
            } else {
                code.trim_end().to_string()
            };
            Entry::Body(format!("{}\n", chunk))
        }
        Language::Elixir => classify_elixir(trimmed, first_line, single),
        Language::Groovy => classify_groovy(trimmed, first_line, single, total_idx),
        Language::Julia => {
            if starts_any(first_line, &["function", "struct", "mutable", "abstract", "module", "macro"]) {
                Entry::Body(format!("{}\n", trimmed))
            } else if single && (starts_any(first_line, &["using", "import", "if", "for", "while", "try", "begin", "let", "return"]) || contains_assignment(trimmed)) {
                Entry::Body(trimmed.to_string())
            } else if single {
                Entry::Body(format!("println({});", strip_semi(trimmed)))
            } else {
                Entry::Body(code.trim_end().to_string())
            }
        }
        Language::Nim => classify_nim(trimmed, first_line, single),
        Language::Perl => {
            if starts_any(first_line, &["sub"]) {
                Entry::Body(format!("{}\n", trimmed))
            } else if single && is_perl_statement(trimmed) {
                Entry::Body(trimmed.to_string())
            } else if single {
                Entry::Body(format!("say({});", strip_semi(trimmed)))
            } else {
                Entry::Body(code.trim_end().to_string())
            }
        }
        Language::Php => Entry::Body(strip_semi(trimmed).to_string()),
        Language::R => {
            if single && (trimmed.contains("<-") || contains_assignment(trimmed) || starts_any(first_line, &["library", "require", "print", "if", "for", "while", "function"])) {
                Entry::Body(trimmed.to_string())
            } else if single {
                Entry::Body(format!("print(({}))", trimmed))
            } else {
                Entry::Body(code.trim_end().to_string())
            }
        }
        Language::Swift => classify_swift(code, trimmed, first_line, single),
        Language::TypeScript => classify_ts(trimmed, first_line, single),
        Language::Zig => classify_zig(code, trimmed, first_line, single),
        _ => Entry::Body(code.trim_end().to_string()),
    }
}

fn is_python_expr(t: &str) -> bool {
    if t.is_empty() || t.contains(';') {
        return false;
    }
    if t.starts_with("print(") {
        return false;
    }
    const KW: &[&str] = &[
        "import", "from", "def", "class", "for", "while", "if", "elif", "else", "try", "except",
        "finally", "with", "return", "del", "global", "nonlocal", "assert", "raise", "pass",
        "break", "continue", "async", "yield",
    ];
    if starts_any(t, KW) || t.starts_with('@') {
        return false;
    }
    // Augmented assignments
    for op in ["+=", "-=", "*=", "/=", "//=", "%=", "**=", "&=", "|=", "^=", ">>=", "<<="] {
        if t.contains(op) {
            return false;
        }
    }
    if contains_assignment(t) {
        return false;
    }
    true
}

fn body_indented(code: &str, indent: &str) -> String {
    indent_all(code.trim_end_matches('\n'), indent)
}

fn classify_go(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("import ") || first_line == "import (" || first_line.starts_with("import(") {
        // Extract quoted import specs (keep alias if present before quote on a line).
        let mut specs = Vec::new();
        for line in trimmed.lines() {
            let l = line.trim();
            if let Some(start) = l.find('"') {
                if let Some(end_rel) = l[start + 1..].find('"') {
                    let quoted = &l[start..=start + 1 + end_rel];
                    let before = l[..start].trim();
                    let alias = before.strip_prefix("import").map(|s| s.trim()).unwrap_or(before);
                    if alias.is_empty() || alias == "(" {
                        specs.push(quoted.to_string());
                    } else {
                        specs.push(format!("{} {}", alias, quoted));
                    }
                }
            }
        }
        if !specs.is_empty() {
            return Entry::Imports(specs);
        }
    }
    if starts_any(first_line, &["func", "var", "const", "type"]) {
        return Entry::Decl(trimmed.to_string());
    }
    let clean = strip_semi(trimmed);
    if single {
        if let Some(pos) = clean.find(":=") {
            let lhs = clean[..pos].trim();
            return Entry::Body(format!("\t{}\n\t_ = {}", clean, lhs));
        }
        let is_stmt = starts_any(clean, &["if", "for", "switch", "select", "return", "go", "defer", "else"])
            || clean.starts_with("fmt.Print")
            || clean.starts_with("print(")
            || clean.starts_with("println(")
            || contains_assignment(clean)
            || clean.ends_with("++")
            || clean.ends_with("--");
        if is_stmt {
            Entry::Body(format!("\t{}", clean))
        } else {
            Entry::Body(format!("\t__print({});", clean))
        }
    } else {
        Entry::Body(body_indented(code, "\t"))
    }
}

fn classify_rust(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    let clean_all = strip_semi(trimmed);
    if starts_any(first_line, &["fn", "pub", "struct", "enum", "trait", "impl", "type", "mod", "use", "const", "static"]) {
        return Entry::Decl(clean_all.to_string());
    }
    if single {
        let is_stmt = starts_any(clean_all, &["let", "return", "if", "for", "while", "loop", "match", "break", "continue"]);
        if is_stmt {
            Entry::Body(format!("    {}", clean_all))
        } else {
            Entry::Body(format!("    __print({});", clean_all))
        }
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn is_c_function_def(t: &str) -> bool {
    if starts_any(t, &["if", "for", "while", "switch", "return", "sizeof"]) {
        return false;
    }
    // e.g. `void foo() { ... }` / `int bar(int x) { ... }`
    let Some(lp) = t.find('(') else { return false };
    if !t.contains('{') {
        return false;
    }
    let before = &t[..lp];
    // need at least two tokens (return type + name)
    before.split_whitespace().count() >= 2
}

fn classify_c(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("#include") && single {
        return Entry::Imports(vec![trimmed.to_string()]);
    }
    if starts_any(first_line, &["struct", "union", "enum", "typedef"]) || is_c_function_def(trimmed) {
        return Entry::Decl(strip_semi(trimmed).to_string());
    }
    let clean = strip_semi(trimmed);
    if single {
        const TYPES: &[&str] = &[
            "int", "char", "long", "short", "unsigned", "signed", "float", "double", "size_t",
            "bool", "_Bool", "void", "const", "static", "extern", "volatile", "register", "auto",
        ];
        let is_decl = starts_any(clean, TYPES);
        let is_inc = clean.ends_with("++") || clean.ends_with("--") || clean.starts_with("++") || clean.starts_with("--");
        let is_aug = ["+=", "-=", "*=", "/=", "%=", "&=", "|=", "^="].iter().any(|op| clean.contains(op));
        if is_decl || is_inc || is_aug {
            Entry::Body(format!("    {}", clean))
        } else {
            Entry::Body(format!("    __print({});", clean))
        }
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn classify_cpp(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if starts_any(first_line, &["struct", "class", "enum", "union", "template", "namespace", "typedef"]) || is_c_function_def(trimmed) {
        return Entry::Decl(strip_semi(trimmed).to_string());
    }
    let clean = strip_semi(trimmed);
    if single {
        const TYPES: &[&str] = &[
            "int", "char", "long", "short", "unsigned", "signed", "float", "double", "size_t",
            "bool", "void", "const", "static", "auto", "std::string", "string", "std::vector", "vector",
        ];
        let is_stmt = starts_any(clean, TYPES)
            || starts_any(clean, &["if", "for", "while", "switch", "return", "do", "else", "using", "#include", "cout", "cerr", "cin"])
            || clean.starts_with("#")
            || contains_assignment(clean)
            || clean.ends_with("++")
            || clean.ends_with("--")
            || ["+=", "-=", "*=", "/="].iter().any(|op| clean.contains(op));
        if is_stmt {
            Entry::Body(format!("    {}", clean))
        } else {
            Entry::Body(format!("    std::cout << ({}) << std::endl;", clean))
        }
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn classify_dart(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("import ") {
        return Entry::Imports(vec![first_line.to_string()]);
    }
    if starts_any(first_line, &["class", "enum", "mixin", "extension", "typedef"])
        || is_dart_function(first_line)
    {
        return Entry::Decl(trimmed.to_string());
    }
    if single {
        let is_stmt = starts_any(trimmed, &["var", "final", "const", "late", "if", "for", "while", "switch", "return", "try"])
            || trimmed.ends_with("++")
            || trimmed.ends_with("--");
        if is_stmt {
            Entry::Body(format!("  {}", trimmed))
        } else {
            Entry::Body(format!("  print(({}));", strip_semi(trimmed)))
        }
    } else {
        Entry::Body(body_indented(code, "  "))
    }
}

fn is_dart_function(line: &str) -> bool {
    // `void foo() {}` / `int foo() {}` style (leading simple type then name + parens)
    let Some(lp) = line.find('(') else { return false };
    if !line.contains('{') {
        return false;
    }
    let before = &line[..lp];
    let toks: Vec<&str> = before.split_whitespace().collect();
    if toks.len() < 2 {
        return false;
    }
    matches!(toks[0], "void" | "int" | "double" | "num" | "bool" | "String" | "dynamic" | "Object")
}

fn classify_kotlin(code: &str, trimmed: &str, first_line: &str, single: bool, body_idx: usize) -> Entry {
    if starts_any(first_line, &["import", "package", "val", "var", "class", "data", "sealed", "interface", "object", "enum", "fun", "suspend", "annotation", "typealias"]) {
        return Entry::Decl(trimmed.to_string());
    }
    if single {
        let is_stmt = starts_any(trimmed, &["println", "print", "for", "while", "return", "when", "throw"])
            || contains_assignment(trimmed);
        if is_stmt {
            Entry::Body(format!("    {}", trimmed))
        } else {
            Entry::Body(format!(
                "    val __repl_val_{} = ({})\n    println(__repl_val_{})",
                body_idx, strip_semi(trimmed), body_idx
            ))
        }
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn classify_haskell(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("import ") {
        return Entry::Imports(vec![first_line.to_string()]);
    }
    if starts_any(first_line, &["data", "newtype", "type", "class", "instance"]) {
        return Entry::Decl(trimmed.to_string());
    }
    if single && is_haskell_binding(trimmed) {
        return Entry::Decl(trimmed.to_string());
    }
    if single && starts_word(trimmed, "let") {
        return Entry::Body(format!("    {}\n    return ()", trimmed));
    }
    if single && starts_word(trimmed, "if") {
        return Entry::Body(format!("    {}", trimmed));
    }
    if single {
        Entry::Body(format!("    print (({}))", trimmed))
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

fn is_haskell_binding(t: &str) -> bool {
    // name (args)* = ...   with a single '=' (not ==)
    let Some(pos) = t.find('=') else { return false };
    if t[pos..].starts_with("==") {
        return false;
    }
    let lhs = t[..pos].trim();
    if lhs.is_empty() {
        return false;
    }
    let first = lhs.split_whitespace().next().unwrap_or("");
    first.chars().next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
        && !matches!(first, "let" | "if" | "case")
        && !lhs.contains("<-")
}

fn classify_csharp(trimmed: &str, single: bool, total_idx: usize) -> Entry {
    if !single {
        return Entry::Body(trimmed.to_string());
    }
    if starts_word(trimmed, "using") || starts_word(trimmed, "return") {
        return Entry::Body(strip_semi(trimmed).to_string());
    }
    let is_stmt = starts_any(
        trimmed,
        &[
            "class", "interface", "struct", "enum", "namespace", "record", "if", "for", "foreach",
            "while", "switch", "try", "Console.WriteLine", "Console.Write", "void", "public",
            "private", "protected", "static", "async",
        ],
    ) || is_csharp_decl(trimmed)
        || contains_assignment(trimmed);
    if is_stmt {
        Entry::Body(trimmed.to_string())
    } else {
        Entry::Body(format!(
            "var __repl_val_{} = ({});\n__run_print(__repl_val_{});",
            total_idx,
            strip_semi(trimmed),
            total_idx
        ))
    }
}

fn is_csharp_decl(t: &str) -> bool {
    // var/int/string/... name = ...  or Type name;
    let mut it = t.split_whitespace();
    let Some(first) = it.next() else { return false };
    if first == "var" {
        return t.contains('=');
    }
    const TYPES: &[&str] = &["int", "string", "double", "float", "bool", "long", "short", "byte", "char", "decimal", "object", "dynamic", "uint", "ulong"];
    if TYPES.contains(&first) {
        return it.next().is_some();
    }
    false
}

fn classify_elixir(trimmed: &str, first_line: &str, single: bool) -> Entry {
    if starts_any(first_line, &["defmodule", "defprotocol", "import", "alias", "use", "require"]) {
        return Entry::Body(format!("{}\n", trimmed));
    }
    if single {
        if let Some(pos) = trimmed.find(" = ") {
            let lhs = trimmed[..pos].trim();
            // simple variable binding
            if lhs.chars().next().is_some_and(|c| c.is_ascii_lowercase() || c == '_')
                && lhs.chars().all(|c| c.is_alphanumeric() || c == '_')
            {
                return Entry::Body(format!("{}\n_ = {}", trimmed, lhs));
            }
        }
        if starts_any(trimmed, &["def", "defp"]) {
            return Entry::Body(trimmed.to_string());
        }
        Entry::Body(format!("IO.inspect(({}))", trimmed))
    } else {
        Entry::Body(trimmed.to_string())
    }
}

fn classify_groovy(trimmed: &str, first_line: &str, single: bool, total_idx: usize) -> Entry {
    if starts_any(first_line, &["import", "class", "interface", "enum", "trait", "package"]) {
        return Entry::Body(trimmed.to_string());
    }
    if !single {
        return Entry::Body(trimmed.to_string());
    }
    // function definition: def name(...) ...
    if starts_word(trimmed, "def") {
        let rest = trimmed[3..].trim_start();
        if rest.contains('(') {
            return Entry::Body(trimmed.to_string());
        }
    }
    let starts_print = trimmed.starts_with("println") || trimmed.starts_with("print ") || trimmed.starts_with("print(");
    if starts_print || starts_any(trimmed, &["if", "for", "while", "switch", "try", "return"]) {
        return Entry::Body(trimmed.to_string());
    }
    Entry::Body(format!(
        "def __run_value_{} = ({});\nprintln(__run_value_{});",
        total_idx,
        strip_semi(trimmed),
        total_idx
    ))
}

fn classify_nim(trimmed: &str, first_line: &str, single: bool) -> Entry {
    if !single {
        return Entry::Body(format!("{}\n", trimmed));
    }
    if starts_any(first_line, &["var", "let", "const"]) {
        let after = first_line.split_whitespace().nth(1).unwrap_or("");
        let name: String = after.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
        return Entry::Body(format!("{}\ndiscard {}\n", trimmed, name));
    }
    if starts_any(
        first_line,
        &["import", "include", "from", "proc", "func", "method", "macro", "template", "iterator", "type", "if", "for", "while", "when", "try", "case"],
    ) {
        return Entry::Body(format!("{}\n", trimmed));
    }
    Entry::Body(format!("echo ({})\n", strip_semi(trimmed)))
}

fn is_perl_statement(t: &str) -> bool {
    starts_any(t, &["my", "our", "local", "state", "use", "no", "require", "sub", "if", "unless", "for", "foreach", "while", "until", "given", "return", "package"])
        || ((t.starts_with('$') || t.starts_with('@') || t.starts_with('%')) && contains_assignment(t))
}

fn classify_swift(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if first_line.starts_with("import ") {
        return Entry::Imports(vec![first_line.to_string()]);
    }
    if starts_any(first_line, &["func", "struct", "class", "enum", "protocol", "extension", "typealias"]) {
        return Entry::Body(format!("{}\n", trimmed));
    }
    if single {
        let is_stmt = starts_any(trimmed, &["let", "var", "if", "for", "while", "switch", "guard", "return", "do"])
            || contains_assignment(trimmed);
        if is_stmt {
            Entry::Body(trimmed.to_string())
        } else {
            Entry::Body(format!("print(({}))", strip_semi(trimmed)))
        }
    } else {
        Entry::Body(code.trim_end().to_string())
    }
}

fn classify_ts(trimmed: &str, first_line: &str, single: bool) -> Entry {
    if !single {
        return Entry::Body(trimmed.to_string());
    }
    if starts_any(
        first_line,
        &["import", "export", "interface", "type", "function", "class", "abstract", "declare", "enum", "namespace", "const", "let", "var", "if", "for", "while", "switch", "try", "return"],
    ) {
        // Observed semicolon stripping on declarations/imports.
        return Entry::Body(strip_semi(trimmed).to_string());
    }
    Entry::Body(format!("__print(await ({}));", strip_semi(trimmed)))
}

fn classify_zig(code: &str, trimmed: &str, first_line: &str, single: bool) -> Entry {
    if starts_any(first_line, &["var", "const", "fn", "pub", "test", "comptime"]) {
        return Entry::Decl(strip_semi(trimmed).to_string());
    }
    if single {
        if starts_any(trimmed, &["if", "for", "while", "switch", "defer", "errdefer"]) {
            Entry::Body(format!("    {}", trimmed))
        } else {
            Entry::Body(format!(
                "    std.debug.print(\"{{any}}\\n\", .{{ {} }});",
                strip_semi(trimmed)
            ))
        }
    } else {
        Entry::Body(body_indented(code, "    "))
    }
}

// ===================== Lua (stateless file) =====================
struct LuaSession {
    ctx: Ctx,
    _temp: tempfile::TempDir,
    path: PathBuf,
}
impl LuaSession {
    fn new(ctx: &Ctx) -> Result<Self> {
        let temp = temp_for_session(Language::Lua)?;
        let path = temp.path().join("session.lua");
        Ok(LuaSession { ctx: ctx.clone(), _temp: temp, path })
    }
}
impl Session for LuaSession {
    fn execute(&mut self, code: &str) -> Result<Outcome> {
        let tools = runner::resolve_tools_no_probe(&self.ctx, Language::Lua, Mode::Inline)?;
        let content = lua_transform(code);
        std::fs::write(&self.path, content)?;
        let out = Command::new(&tools.primary)
            .arg("session.lua")
            .current_dir(self.path.parent().unwrap())
            .output()?;
        print_full(&String::from_utf8_lossy(&out.stdout), false);
        print_full(&String::from_utf8_lossy(&out.stderr), true);
        Ok(Outcome { status: Some(out.status) })
    }
}

fn lua_transform(code: &str) -> String {
    let t = code.trim();
    let is_stmt = starts_any(t, &["local", "function", "if", "for", "while", "repeat", "do", "return", "break", "goto", "end", "else", "elseif"])
        || contains_assignment(t);
    if is_stmt || t.contains('\n') {
        return runner::ensure_nl(code);
    }
    format!(
        "do\n    local __run_pack = table.pack(({}))\n    local __run_n = __run_pack.n or #__run_pack\n    if __run_n > 0 then\n        for __run_i = 1, __run_n do\n            if __run_i > 1 then io.write(\"\\t\") end\n            local __run_val = __run_pack[__run_i]\n            if __run_val == nil then\n                io.write(\"nil\")\n            else\n                io.write(tostring(__run_val))\n            end\n        end\n        io.write(\"\\n\")\n    end\nend\n",
        t
    )
}

