impl Session for FileSession {
    fn execute(&mut self, code: &str) -> Result<Outcome> {
        let tools = self.tools()?;
        let entry = classify(self.lang, code, self.body.len(), self.total_entries);
        let mut imports = self.imports.clone();
        let mut decls = self.decls.clone();
        let mut body = self.body.clone();
        match &entry {
            Entry::Imports(list) => {
                for item in list {
                    if !imports.contains(item) {
                        imports.push(item.clone());
                    }
                }
            }
            Entry::Decl(chunk) => decls.push(chunk.clone()),
            Entry::Body(chunk) => body.push(chunk.clone()),
        }
        // C# project file is (re)written alongside the session source.
        if self.lang == Language::CSharp {
            let proj = self.session_path.parent().unwrap().join("Run.csproj");
            std::fs::write(&proj, csharp_project(&self.ctx))?;
        }
        let content = self.build_file(&imports, &decls, &body);
        std::fs::write(&self.session_path, content)?;
        let (status, stdout, stderr) = self.run_once(&tools)?;
        print_diff(&self.last_stdout, &stdout, false);
        print_diff(&self.last_stderr, &stderr, true);
        if status.success() {
            self.imports = imports;
            self.decls = decls;
            self.body = body;
            self.total_entries += 1;
            self.last_stdout = stdout;
            self.last_stderr = stderr;
        }
        Ok(Outcome { status: Some(status) })
