import pty,os,time,select,sys,re,pathlib,shutil

def run(bin,home,seq,args=["python"]):
    shutil.rmtree(home,ignore_errors=True); os.makedirs(home,exist_ok=True)
    env=dict(os.environ); env["HOME"]=home
    pid,fd=pty.fork()
    if pid==0: os.execve(bin,[bin]+args,env)
    def read(t=.7):
        d=b""; e=time.time()+t
        while time.time()<e:
            r,_,_=select.select([fd],[],[],.05)
            if r:
                try:c=os.read(fd,8192)
                except: break
                if not c:break
                d+=c; e=time.time()+.25
        return d
    outs=[read()]
    for s in seq:
        try: os.write(fd,s)
        except: break
        outs.append(read())
