import pty,os,time,select,sys

def run(bin,env_extra,inputs=[b"print(1)\n",b"\x04"]):
 pid,fd=pty.fork()
 if pid==0:
  env=dict(os.environ);env.update(env_extra);os.execve(bin,[bin,"python"],env)
 def read():
  d=b"";e=time.time()+.8
  while time.time()<e:
   r,_,_=select.select([fd],[],[],.1)
   if r:
    try:c=os.read(fd,8192)
    except:break
    d+=c;e=time.time()+.25
  return d
 outs=[read()]
 for i in inputs:
  os.write(fd,i);outs.append(read())
 try:
  p,st=os.waitpid(pid,os.WNOHANG);code=os.waitstatus_to_exitcode(st) if p else "alive"
 except Exception as e:code=str(e)
 return code,outs
for label,env in [("TERM dumb",{"TERM":"dumb"}),("TERM empty",{"TERM":""}),("NO_COLOR",{"NO_COLOR":"1"}),("TERM unknown",{"TERM":"unknown-xyz"})]:
 print("\n",label)
 for bin in ["/workspace/executable","/tmp/ourbin/executable"]:
  code,outs=run(bin,env);print(bin,code,[repr(o) for o in outs])
