import os,pty,subprocess,select,time,sys

def test(bin,mode):
    master,slave=pty.openpty()
    if mode=="stdin_tty_stdout_pipe":
        p=subprocess.Popen([bin,"python"],stdin=slave,stdout=subprocess.PIPE,stderr=subprocess.PIPE,close_fds=True,env={**os.environ,"HOME":"/tmp/hcombo"})
        os.close(slave)
        os.write(master,b"print(42)\n")
        time.sleep(1)
        os.write(master,b"\x04")
        time.sleep(1)
        alive=p.poll()
        if alive is None:
            p.kill()
        out=b"";err=b""
        try:
            out,err=p.communicate(timeout=2)
        except Exception as e:out=str(e).encode()
        # read any from master (echo)
        m=b""
        while True:
            r,_,_=select.select([master],[],[],0.2)
            if not r:break
            try:m+=os.read(master,9999)
            except:break
        os.close(master);return alive,out,err,m
    if mode=="stdin_pipe_stdout_tty":
        p=subprocess.Popen([bin,"python"],stdin=subprocess.PIPE,stdout=slave,stderr=slave,close_fds=True,env={**os.environ,"HOME":"/tmp/hcombo"})
        os.close(slave)
        out,err=p.communicate(input=b"print(43)\n",timeout=5)
        m=b""
        while True:
            r,_,_=select.select([master],[],[],0.2)
            if not r:break
            try:m+=os.read(master,9999)
            except:break
        os.close(master);return p.returncode,out,err,m

