p=open("src/repl.rs").read()
# compiled binary cwd original
p=p.replace("capture(Command::new(&out_bin).current_dir(temp))", "capture(&mut Command::new(&out_bin))")
p=p.replace("let res = capture(Command::new(&out_bin).current_dir(temp));", "let res = capture(&mut Command::new(&out_bin));")
# The capture closure expects &mut Command; other call sites pass owned Command by value - in Rust, capture(Command::new...) where param is &mut Command works via temporary? It compiled before because function argument coercion? capture defined as |cmd: &mut Command| and calls with Command value auto-ref temporary. Our replacement &mut is fine.
# Go unused import suppression in execute: after first run_with_entry, before fallback
old='''        let (mut status, mut stdout, mut stderr, mut imports, mut decls, mut body) =
            self.run_with_entry(&tools, &raw_entry)?;'''
new='''        let (mut status, mut stdout, mut stderr, mut imports, mut decls, mut body) =
            self.run_with_entry(&tools, &raw_entry)?;
        if !status.success()
            && self.lang == Language::Go
            && matches!(raw_entry, Entry::Imports(_))
            && stderr.contains("imported and not used")
            && stderr.lines().all(|l| {
                l.trim().is_empty()
                    || l.starts_with("#")
                    || l.contains("imported and not used")
            })
        {
            // An import on its own is not yet used; keep it for later lines
            // instead of reporting the compiler's unused-import error.
            self.imports = imports;
            self.total_entries += 1;
            return Ok(Outcome { status: None });
        }'''
assert old in p; p=p.replace(old,new)
open("src/repl.rs","w").write(p)
PY
