import pty,os,time,select,sys,struct,fcntl,termios

def run(bin):
 pid,fd=pty.fork()
 if pid==0:os.environ["HOME"]="/tmp/hlong";os.execv(bin,[bin,"python"])
 # set winsize 80x24
 fcntl.ioctl(fd,termios.TIOCSWINSZ,struct.pack("HHHH",24,80,0,0))
 def read():
  d=b"";e=time.time()+.5
  while time.time()<e:
   r,_,_=select.select([fd],[],[],.05)
   if r:d+=os.read(fd,99999);e=time.time()+.2
  return d
 read();os.write(fd,b"x"*85);d=read();print(bin,repr(d))
 os.write(fd,b"\n");print("enter",repr(read()))
 os.write(fd,b"\x04");print("eof",repr(read()))
for b in ["/workspace/executable","/tmp/ourbin/executable"]:run(b)
PY
